/* ── section captions for the effect rail ─────────────────────────────────
   The server tags every effect with a `cat`; this is the order they appear in
   and what the caption says. An effect whose cat is not listed lands under
   "Other" rather than disappearing — a new category on the server must not be
   able to hide a tool. */
var SXT_CATS = [
  ['core',       'Core'],
  ['dynamics',   'Level'],
  ['tone',       'Tone'],
  ['time',       'Time'],
  ['space',      'Space'],
  ['modulation', 'Modulation'],
  ['restore',    'Repair'],
  ['utility',    'Utility'],
  ['plugin',     'Plugins'],
  ['other',      'Other']
];

/* ── which EDGE each effect family is drawn on ───────────────────────
   SXT_CATS says what a family is called and in what order; this says which
   BAR it lands in. The server's `cat` keeps naming the FAMILY and never a
   screen edge, so flipping a value here moves a whole family between the two
   bars with nothing else to keep in step, and a new category on the server
   still appears (it falls through to the rail).

   The cut is by QUESTION, not by count: the dock takes what makes a sound
   SIT — level, repair, the utility plumbing — beside the session half that is
   already there; the rail keeps what makes a sound sound DIFFERENT (core,
   tone, time, space, modulation, plugins). Measured at the operator's zoom
   (2507x1567) that is also what stops both bars scrolling: 74 effects two
   across was 1.68 screens of rail. */
var SXT_PLACE = {dynamics:'dock', restore:'dock', utility:'dock'};
function sxtEdge(cat){ return SXT_PLACE[cat]==='dock' ? 'dock' : 'side'; }
/* the server's effect roster, grouped by family — both bars read this, so the
   grouping (and the "an unknown cat lands in Other" rule) lives in one place */
function sxtFxByCat(){
  var types=(MG.spec&&MG.spec.effect_types)||[], by={};
  types.forEach(function(e){
    var c=e.cat||(e.id.indexOf('lsp_')===0?'plugin':'other');
    if(!SXT_CATS.some(function(x){ return x[0]===c; })) c='other';
    (by[c]=by[c]||[]).push(e);
  });
  return by;
}
/* one effect icon, wherever it is drawn — the dot that says "already in this
   layer's chain" and the notch that says "not one of ours" travel with it */
function sxtFxTool(e, cat){
  return sxtToolHtml({id:e.id, lb:e.title,
    tip:(e.racks&&e.racks[0]&&e.racks[0].sub)||'add this effect to the selected sound'},
    sxtChainHas(e.id), cat==='plugin');
}

function sxtIcon(id){
  var g=SXT_ICON[id] || '<rect x="5" y="5" width="14" height="14" rx="3"/>';
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"'
    + ' stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+g+'</svg>';
}
/* a one-shot action has no state to latch, so it lights for 420 ms instead —
   you can see the click took without the button claiming a mode it has not got */
function sxtFlash(id){
  Array.prototype.forEach.call(document.querySelectorAll('[data-sxt="'+id+'"]'), function(el){
    el.classList.add('flash'); setTimeout(function(){ el.classList.remove('flash'); }, 420);
  });
}

/* ── what the tools act on ────────────────────────────────────────────────
   In order: the card selected on the board, else the library row you last
   played — which gets added to the merge first. "Modify this sfx" and "put
   this sfx on the board" are the same operation here: a one-layer merge IS a
   modified sound, and Save layer writes it back to the library as one. */
function sxtTarget(){
  if(MG.sel){ var it=mgItem(MG.sel); if(it) return it; }
  if(MG.items.length===1) return MG.items[0];
  return null;
}
function sxtWithTarget(cb, what){
  var it=sxtTarget();
  if(it){ cb(it); return; }
  var r=SX.curRec;
  if(!r){
    mgStatus((what||'that')+' needs a sound — click one in the library, or a card on the board',
             'var(--warn)');
    return;
  }
  mgAdd(r, {then:function(){
    var l=mgFind(r.c, r.f); var t=l[l.length-1];
    if(t){ mgSelect(t.uid); cb(t); }
  }});
}
/* every structural edit goes through here first, so undo has something to
   return to. The snapshot is the layer list only — zoom, loop and the playhead
   are view state and restoring them would move the screen under you. */
function sxtSnapshot(tag){
  try{
    SXT.hist.push({tag:tag||'', items:JSON.stringify(MG.items.map(function(i){
      return {uid:i.uid,c:i.c,f:i.f,n:i.n,d:i.d,start:i.start,slots:i.slots,
              label:i.label,color:i.color,muted:i.muted,hideName:i.hideName}; })),
      sel:MG.sel});
  }catch(e){ return; }
  if(SXT.hist.length>SXT_UNDO_CAP) SXT.hist.shift();
  SXT.future.length=0;
  sxtRender();
}
function sxtStateNow(){
  return JSON.stringify(MG.items.map(function(i){
    return {uid:i.uid,c:i.c,f:i.f,n:i.n,d:i.d,start:i.start,slots:i.slots,
            label:i.label,color:i.color,muted:i.muted,hideName:i.hideName}; }));
}
function sxtRestore(snap){
  var byKey={}; SX.all.forEach(function(x){ byKey[x.c+'|'+x.f]=x; });
  var arr=[]; try{ arr=JSON.parse(snap.items)||[]; }catch(e){ return false; }
  MG.items=arr.filter(function(i){ return byKey[i.c+'|'+i.f]; }).map(function(i){
    var src=byKey[i.c+'|'+i.f];
    return {uid:i.uid, c:i.c, f:i.f, n:i.n||src.n, d:src.d||i.d||0, start:+i.start||0,
            slots:Array.isArray(i.slots)?i.slots:[], dur:src.d||i.d||0, stem:'', url:'',
            label:i.label||'', color:i.color||'', muted:!!i.muted, hideName:!!i.hideName};
  });
  MG.sel=snap.sel||null; MG.selIds=MG.sel?[MG.sel]:[]; MG.mixDirty=true;
  if(MG.mixer) mgMixerDraw();
  mgRenderBoard(); mgPersist(); sxtRender();
  mgRender({why:'restore', play:false});
  return true;
}
function sxtUndo(){
  if(!SXT.hist.length){ mgStatus('nothing to undo'); return; }
  SXT.future.push({items:sxtStateNow(), sel:MG.sel});
  sxtRestore(SXT.hist.pop()); mgStatus('undone');
}
function sxtRedo(){
  if(!SXT.future.length){ mgStatus('nothing to redo'); return; }
  SXT.hist.push({items:sxtStateNow(), sel:MG.sel});
  sxtRestore(SXT.future.pop()); mgStatus('redone');
}

/* ── the effect rail ──────────────────────────────────────────────────── */
function sxtAddFx(typ){
  sxtWithTarget(function(it){
    var max=(MG.spec&&MG.spec.max_slots)||10;
    if((it.slots||[]).length>=max){
      mgStatus('this layer already holds '+max+' effects — remove one first','var(--warn)');
      return;
    }
    sxtSnapshot('add '+typ);
    mgSlotAdd(it.uid, typ);          /* appends the slot, re-renders, opens its knobs */
    sxtRender();
  }, 'an effect');
}
/* the rail doubles as a read-out: an effect already in the selected layer's
   chain wears a dot, so you can see what is on this sound without opening the
   mixer */
function sxtChainHas(typ){
  var it=sxtTarget(); if(!it||!it.slots) return false;
  for(var i=0;i<it.slots.length;i++) if(it.slots[i].type===typ) return true;
  return false;
}
function sxtToolHtml(t, inChain, plug){
  return '<div class="sxt-tool'+(t.on?' on':'')+(inChain?' inchain':'')+(plug?' plug':'')
    + (t.off?' off':'')+'" data-sxt="'+esc(t.id)+'" role="button"'
    + ' title="'+esc(String(t.lb))+(t.k?' ('+t.k+')':'')+' — '+esc(t.tip||'')+'">'
    + sxtIcon(t.icon||t.id)+'</div>';
}
function sxtRailRender(){
  var host=document.getElementById('sxt-tools'); if(!host) return;
  var types=(MG.spec&&MG.spec.effect_types)||[];
  if(!types.length){
    host.innerHTML='<div class="sxt-sec">Effects</div>'
      + '<div style="color:var(--muted);font-size:.62rem;text-align:center;padding:8px">'
      + 'the merger has not answered yet</div>';
    return;
  }
  var by=sxtFxByCat();
  var html='';
  SXT_CATS.forEach(function(pair){
    if(sxtEdge(pair[0])!=='side') return;      /* this family is drawn in the dock */
    var list=by[pair[0]]; if(!list||!list.length) return;
    html += '<div class="sxt-sec">'+esc(pair[1])+'</div><div class="sxt-row">'
      + list.map(function(e){ return sxtFxTool(e, pair[0]); }).join('')
      + '</div>';
  });
  host.innerHTML=html;
}

/* ── the dock: the session half ───────────────────────────────────────── */
function SXT_DOCK(){ return [
 {sec:'Transport', items:[
   {id:'t_play', lb:'Play / pause', on:MG.playing,
    tip:'play or pause the merge as it currently stands', fn:mgTogglePlay},
   {id:'t_stop', lb:'Stop', tip:'stop and rewind to the start', fn:function(){ mgStop(); }},
   {id:'t_replay', lb:'Replay', tip:'play again from the start', fn:mgReplay},
   {id:'t_loop', lb:'Loop', on:MG.loop,
    tip:'loop the merge — a layer added while looping keeps it looping', fn:mgToggleLoop},
   {id:'t_solo', lb:'Solo layer', tip:'play the selected layer alone, with its chain applied',
    fn:function(){ sxtWithTarget(function(it){
      if(!it.url){ mgStatus('that layer has not rendered yet'); return; }
      MG.headBase=it.start; mgPlayUrl(it.url, 0, true); mgStatus('solo · '+it.n); }, 'solo'); }},
 ]},
 {sec:'Timeline', items:[
   {id:'t_zoomin', lb:'Zoom in', k:'+', tip:'zoom the ruler in', fn:function(){ mgZoom(1); }},
   {id:'t_zoomout', lb:'Zoom out', k:'−', tip:'zoom the ruler out', fn:function(){ mgZoom(-1); }},
   {id:'t_zoomfit', lb:'Fit', k:'0', tip:'fit the whole merge on screen', fn:mgZoomFit},
   {id:'t_taller', lb:'Taller lanes', tip:'make every lane taller', fn:function(){ mgLaneZoom(8); }},
   {id:'t_shorter', lb:'Shorter lanes', tip:'make every lane shorter', fn:function(){ mgLaneZoom(-8); }},
   {id:'t_nudgel', lb:'Nudge earlier', tip:'move the selected layer 10 ms earlier',
    fn:function(){ sxtNudge(-0.01); }},
   {id:'t_nudger', lb:'Nudge later', tip:'move the selected layer 10 ms later',
    fn:function(){ sxtNudge(0.01); }},
   {id:'t_stamp', lb:'Set timestamp', tip:'type an exact start time for the selected layer',
    fn:function(){ sxtWithTarget(function(it){ mgTsOpen(it.uid); }, 'a timestamp'); }},
 ]},
 {sec:'Layer', items:[
   {id:'t_addlayer', lb:'Add sound', tip:'add the sound playing in the library as a new layer',
    fn:function(){ if(SX.curRec) mgAdd(SX.curRec); else mgStatus('play a sound in the library first','var(--warn)'); }},
   {id:'t_dup', lb:'Duplicate', tip:'copy the selected layer, chain and all',
    fn:function(){ sxtWithTarget(function(it){ sxtSnapshot('duplicate'); mgTrackClone(it.uid); sxtRender(); }, 'duplicate'); }},
   {id:'t_dellayer', lb:'Remove layer', tip:'take the selected layer off the board',
    fn:function(){ sxtWithTarget(function(it){ sxtSnapshot('remove'); mgRemove(it.uid); sxtRender(); }, 'remove'); }},
   {id:'t_mute', lb:'Mute', tip:'mute or unmute the selected layer',
    fn:function(){ sxtWithTarget(function(it){ sxtSnapshot('mute'); mgTrackMute(it.uid, !it.muted); sxtRender(); }, 'mute'); }},
   {id:'t_colour', lb:'Name & colour', tip:'rename the selected layer or give it a colour',
    fn:function(){ sxtWithTarget(function(it){ mgTkEditOpen(it.uid); }, 'rename'); }},
   {id:'t_up', lb:'Move up', tip:'move the selected layer one lane up',
    fn:function(){ sxtWithTarget(function(it){ sxtSnapshot('move'); mgTrackMove(it.uid,-1); }, 'move'); }},
   {id:'t_down', lb:'Move down', tip:'move the selected layer one lane down',
    fn:function(){ sxtWithTarget(function(it){ sxtSnapshot('move'); mgTrackMove(it.uid,1); }, 'move'); }},
   {id:'t_clearall', lb:'Clear board', tip:'empty the merge list (undoable)',
    fn:function(){ if(!MG.items.length) return; sxtSnapshot('clear'); mgClear(); sxtRender(); }},
 ]},
 {sec:'Chain', items:[
   {id:'t_mixer', lb:'Mixer', tip:'open the slot list for the selected layer',
    fn:function(){ sxtWithTarget(function(it){ mgMixerOpen(it.uid); }, 'the mixer'); }},
   {id:'t_bypass', lb:'Bypass (A/B)', on:!!SXT.ab,
    tip:'silence the whole chain on the selected layer and put it back — the only honest way to hear what it did',
    fn:sxtBypass},
   {id:'t_chainclear', lb:'Clear chain', tip:'take every effect off the selected layer',
    fn:function(){ sxtWithTarget(function(it){
      if(!(it.slots||[]).length){ mgStatus('that layer has no effects'); return; }
      sxtSnapshot('clear chain'); it.slots=[];
      if(MG.mixer===it.uid) mgMixerDraw(); mgSlotsChanged(it); sxtRender(); }, 'clear chain'); }},
   {id:'t_copy', lb:'Copy chain', tip:'copy the selected layer’s whole effect chain',
    fn:function(){ sxtWithTarget(function(it){
      SXT.clip=JSON.parse(JSON.stringify(it.slots||[]));
      try{ localStorage.setItem('sx.chainclip', JSON.stringify(SXT.clip)); }catch(e){}
      mgStatus('copied '+SXT.clip.length+' effect'+(SXT.clip.length===1?'':'s')); sxtRender(); }, 'copy'); }},
   {id:'t_paste', lb:'Paste chain', off:!SXT.clip,
    tip:'replace the selected layer’s chain with the copied one',
    fn:function(){ if(!SXT.clip){ mgStatus('nothing copied yet'); return; }
      sxtWithTarget(function(it){ sxtSnapshot('paste chain');
        it.slots=JSON.parse(JSON.stringify(SXT.clip));
        if(MG.mixer===it.uid) mgMixerDraw(); mgSlotsChanged(it); sxtRender();
        mgStatus('pasted '+it.slots.length+' effect'+(it.slots.length===1?'':'s')); }, 'paste'); }},
   {id:'t_applyall', lb:'Apply to every layer', off:!SXT.clip,
    tip:'give every layer on the board the copied chain',
    fn:function(){ if(!SXT.clip){ mgStatus('copy a chain first','var(--warn)'); return; }
      if(!MG.items.length) return;
      if(!confirm('Replace the effect chain on all '+MG.items.length+' layers with the copied one?')) return;
      sxtSnapshot('apply to all');
      MG.items.forEach(function(it){ it.slots=JSON.parse(JSON.stringify(SXT.clip)); });
      MG.mixDirty=true; if(MG.mixer) mgMixerDraw(); mgPersist(); mgRenderBoard();
      mgRender({why:'tweak', play:false}); sxtRender();
      mgStatus('applied to '+MG.items.length+' layers'); }},
   {id:'t_undo', lb:'Undo', k:'ctrl+Z', off:!SXT.hist.length, tip:'undo the last board or chain edit', fn:sxtUndo},
   {id:'t_redo', lb:'Redo', k:'ctrl+shift+Z', off:!SXT.future.length, tip:'redo what you just undid', fn:sxtRedo},
 ]},
 {sec:'Presets', items:[
   {id:'t_presetsave', lb:'Save chain preset', tip:'store the selected layer’s chain under a name',
    fn:sxtPresetSave},
   {id:'t_presetload', lb:'Load chain preset', tip:'put a stored chain onto the selected layer',
    fn:sxtPresetLoad},
 ]},
 {sec:'Measure', items:[
   {id:'t_stats', lb:'Analyse', tip:'peak, RMS, LUFS, true peak, crest, DC, dynamic range — measured on the sound as it stands',
    fn:function(){ sxtAnalyze('stats'); }},
   {id:'t_spectro', lb:'Spectrogram', tip:'draw the spectrogram of the selected sound after its chain',
    fn:function(){ sxtAnalyze('spectrogram'); }},
   {id:'t_wave', lb:'Waveform', tip:'draw the full waveform of the selected sound after its chain',
    fn:function(){ sxtAnalyze('waveform'); }},
   {id:'t_lufs', lb:'Loudness', tip:'EBU R128 integrated loudness and range',
    fn:function(){ sxtAnalyze('loudness'); }},
   {id:'t_clipcheck', lb:'Clip check', tip:'true peak against 0 dBFS — is this layer clipping right now?',
    fn:function(){ sxtAnalyze('clip'); }},
 ]},
 {sec:'Library', items:[
   {id:'t_record', lb:'Record', tip:'record from an input device straight into a new layer',
    fn:function(){ sxtWithTarget(function(it){ mgMixerOpen(it.uid);
      mgStatus('pick an input above the slot list, then press record'); }, 'record'); }},
   {id:'t_import', lb:'Import file', tip:'bring an audio file in from this machine as a new sound',
    fn:function(){ var f=document.getElementById('sxt-file'); if(f){ f.value=''; f.click(); } }},
   {id:'t_savemerge', lb:'Save merge', tip:'save every layer as one new sfx in the Merged library',
    fn:mgSave},
   {id:'t_savelayer', lb:'Save this layer', tip:'save the selected layer alone — this is how a modified sfx goes back into the library',
    fn:sxtSaveLayer},
   {id:'t_export', lb:'Export file', tip:'render and download: wav 16/24/32, flac, mp3, ogg, opus, aiff, any sample rate',
    fn:sxtExport},
   {id:'t_recipe', lb:'Open recipe', tip:'reopen a saved merge as its layers, chains and timings',
    fn:function(){ var r=SX.curRec;
      if(!r||r.c!=='merged'){ mgStatus('play a file from the Merged library first','var(--warn)'); return; }
      mgOpenRecipe(r); }},
   {id:'t_licence', lb:'Licence', tip:'the licence the selected sound carries, and what a merge of it would inherit',
    fn:sxtLicence},
 ]},
 {sec:'View', items:[
   {id:'t_rail', lb:'Hide the bars', on:!SXT.bars, tip:'hide or show the effect rail and this dock',
    fn:sxtBarsToggle},
   {id:'t_help', lb:'Help', tip:'what every part of this toolbox does', fn:sxtHelp},
 ]},
];}
function sxtDockRender(){
  var host=document.getElementById('sxt-dock'); if(!host) return;
  var by=sxtFxByCat(), grp=function(cap, inner){
    return '<div class="sxt-dgrp"><span class="sxt-dsec">'+esc(cap)+'</span>'
      + '<div class="sxt-dgrid">'+inner+'</div></div>'; };
  /* the dock's OWN family first, the guest effect families after it — a bar
     that opened with a guest group would read as the wrong bar */
  var html = SXT_DOCK().map(function(sec){
    return grp(sec.sec, sec.items.map(function(t){ return sxtToolHtml(t, false, false); }).join('')); }).join('');
  SXT_CATS.forEach(function(pair){
    if(sxtEdge(pair[0])!=='dock') return;
    var list=by[pair[0]]; if(!list||!list.length) return;
    html += grp(pair[1], list.map(function(e){ return sxtFxTool(e, pair[0]); }).join(''));
  });
  host.innerHTML='<div class="sxt-dockgrid">'+html+'</div>';
}
function sxtRender(){ sxtRailRender(); sxtDockRender(); }
/* mgRenderBoard() is the one place every board change goes through, so that is
   where the bars are kept in step. Coalesced to one rebuild per animation
   frame: 119 buttons is not a per-frame cost, and a restore fires several
   board renders in a row. */
function sxtRenderSoon(){
  if(SXT._raf) return;
  SXT._raf=requestAnimationFrame(function(){ SXT._raf=0;
    var v=document.getElementById('view-sfx');
    if(v && v.style.display!=='none') sxtRender(); });
}

/* one delegated handler for both bars: the tool tables are rebuilt on every
   state change, so per-button listeners would leak */
document.addEventListener('click', function(e){
  var el=e.target.closest?e.target.closest('#sxt-tools .sxt-tool,#sxt-dock .sxt-tool'):null;
  if(!el) return;
  var id=el.getAttribute('data-sxt');
  if(el.classList.contains('off')) return;
  var dockItem=null;
  SXT_DOCK().forEach(function(s){ s.items.forEach(function(t){ if(t.id===id) dockItem=t; }); });
  if(dockItem){ sxtFlash(id); dockItem.fn(); sxtRender(); return; }
  sxtFlash(id); sxtAddFx(id);                    /* everything else is an effect id */
});

function sxtNudge(dt){
  sxtWithTarget(function(it){
    sxtSnapshot('nudge');
    it.start=Math.max(0, Math.min(600, +(it.start+dt).toFixed(3)));
    mgRenderBoard(); mgPersist(); mgRender({why:'move', play:false});
    mgStatus(it.n+' at '+mgFmt(it.start));
  }, 'nudge');
}
/* A/B. Not a "disable" flag on the server — the stems are cached on the chain,
   so emptying the list and putting it back costs one render each way and is
   guaranteed to be the same audio the library holds. */
function sxtBypass(){
  var it=sxtTarget();
  if(!it){ mgStatus('select a layer to bypass','var(--warn)'); return; }
  if(SXT.ab && SXT.ab.uid===it.uid){
    it.slots=SXT.ab.slots; SXT.ab=null; mgStatus('chain back on');
  } else {
    if(!(it.slots||[]).length){ mgStatus('that layer has no chain to bypass'); return; }
    SXT.ab={uid:it.uid, slots:it.slots}; it.slots=[]; mgStatus('chain bypassed — click again to restore','var(--warn)');
  }
  if(MG.mixer===it.uid) mgMixerDraw();
  mgSlotsChanged(it); sxtRender();
}

/* ── presets: a named chain, in this browser. Deliberately local — a chain is
   a working note, and writing every experiment into the library as an asset is
   how a library stops being browsable. ── */
function sxtPresets(){ try{ return JSON.parse(localStorage.getItem('sx.presets')||'{}')||{}; }catch(e){ return {}; } }
function sxtPresetSave(){
  sxtWithTarget(function(it){
    if(!(it.slots||[]).length){ mgStatus('that layer has no chain to save','var(--warn)'); return; }
    var name=prompt('Name this chain ('+it.slots.length+' effect'+(it.slots.length===1?'':'s')+'):','');
    if(name==null) return; name=name.trim(); if(!name) return;
    var all=sxtPresets(); all[name]=it.slots;
    try{ localStorage.setItem('sx.presets', JSON.stringify(all)); }catch(e){
      mgStatus('could not store the preset','var(--bad)'); return; }
    mgStatus('saved chain preset "'+name+'"','var(--good)');
  }, 'a preset');
}
function sxtPresetLoad(){
  var all=sxtPresets(), names=Object.keys(all).sort();
  if(!names.length){ mgStatus('no chain presets stored yet'); return; }
  sxtWithTarget(function(it){
    var entries=names.map(function(n){
      return {label:esc(n), note:all[n].length+' fx', fn:function(){
        sxtSnapshot('preset '+n); it.slots=JSON.parse(JSON.stringify(all[n]));
        if(MG.mixer===it.uid) mgMixerDraw(); mgSlotsChanged(it); sxtRender();
        mgStatus('loaded "'+n+'"'); }};
    });
    entries.push({sep:true});
    entries.push({label:'&#10060;&nbsp; Forget a preset…', danger:true, fn:function(){
      var n=prompt('Forget which preset?\n\n'+names.join('\n'),names[0]);
      if(n==null) return; var a=sxtPresets(); if(!(n in a)){ mgStatus('no preset by that name'); return; }
      delete a[n]; try{ localStorage.setItem('sx.presets', JSON.stringify(a)); }catch(e){}
      mgStatus('forgot "'+n+'"'); }});
    var b=document.querySelector('#sxt-dock [data-sxt="t_presetload"]');
    var r=b?b.getBoundingClientRect():{left:window.innerWidth/2, top:window.innerHeight/2};
    mgMenu({clientX:r.left, clientY:Math.max(60, r.top-entries.length*34)}, entries);
  }, 'a preset');
}

/* ── save one layer back into the library ─────────────────────────────────
   The whole point of the toolbox: take a library sfx, put sixty effects on it,
   and put the RESULT back as a new asset with a derived licence and a recipe
   that reopens it. save_mix already does exactly that for a list of layers —
   a list of one is a modified sound. */
function sxtSaveLayer(){
  sxtWithTarget(function(it){
    if(it.muted){ mgStatus('that layer is muted — unmute it before saving','var(--warn)'); return; }
    var n=(it.slots||[]).length;
    var def=(it.label||it.n||'sfx')+(n?' (edited)':'');
    var name=prompt('Save this layer as a new sfx in the Merged library'
      + (n?(' — '+n+' effect'+(n===1?'':'s')+' baked in'):' — no effects on it, this saves a copy')
      + ':', def);
    if(name==null) return; name=name.trim(); if(!name) return;
    mgStatus('saving…');
    vsPost('/inspect/api/merge/save', {name:name, items:[
      {uid:it.uid, cat:it.c, f:it.f, name:it.n, start:0, slots:it.slots||[]}]})
     .then(function(d){
       mgStatus('saved merged/'+d.file+(d.commercial_ok?'':' — licence UNVERIFIED'),
                d.commercial_ok?'var(--good)':'var(--warn)');
       SX.cat='merged'; SX.sel=null; SX.sort='new'; SX.dir=-1;
       SX.q=''; SX.clean=false; SX.noverbal=false; sxLoad(true);
     }).catch(function(e){ mgStatus('save failed: '+(e.message||e),'var(--bad)'); });
  }, 'save');
}

/* ── export ───────────────────────────────────────────────────────────── */
var SXT_FORMATS=[['wav24','WAV 24-bit'],['wav16','WAV 16-bit'],['wav32','WAV 32-bit float'],
                 ['flac','FLAC'],['mp3','MP3 320'],['ogg','OGG Vorbis'],['opus','Opus 192'],
                 ['aiff','AIFF 16-bit']];
var SXT_RATES=[48000,44100,96000,32000,22050,16000,8000];
function sxtExport(){
  if(!MG.items.length){ mgStatus('nothing on the board to export','var(--warn)'); return; }
  var live=MG.items.filter(function(i){ return !i.muted; });
  if(!live.length){ mgStatus('every layer is muted','var(--warn)'); return; }
  var fl=SXT_FORMATS.map(function(f,i){ return (i+1)+') '+f[1]; }).join('\n');
  var pick=prompt('Export '+live.length+' layer'+(live.length===1?'':'s')+' as:\n\n'+fl
                  +'\n\nType a number:', '1');
  if(pick==null) return;
  var f=SXT_FORMATS[(parseInt(pick,10)||1)-1]; if(!f){ mgStatus('no such format'); return; }
  var rs=prompt('Sample rate:\n\n'+SXT_RATES.map(function(r,i){ return (i+1)+') '+r+' Hz'; }).join('\n')
                +'\n\nType a number:', '1');
  if(rs==null) return;
  var rate=SXT_RATES[(parseInt(rs,10)||1)-1]||48000;
  var name=prompt('File name (no extension):', (MG.lastName||'sfx export'));
  if(name==null) return;
  mgStatus('rendering the export…');
  vsPost('/inspect/api/merge/export', {
    items: live.map(function(i){ return {uid:i.uid, cat:i.c, f:i.f, name:i.n, start:i.start, slots:i.slots}; }),
    format:f[0], rate:rate, name:name})
   .then(function(d){
     mgStatus('exported '+f[1]+' @ '+rate+' Hz · '+(d.bytes/1048576).toFixed(2)+' MB','var(--good)');
     var a=document.createElement('a'); a.href=d.url; a.download=(name||'sfx')+'.'+d.ext;
     document.body.appendChild(a); a.click(); document.body.removeChild(a);
   }).catch(function(e){ mgStatus('export failed: '+(e.message||e),'var(--bad)'); });
}
function sxtImport(files){
  if(!files||!files.length) return;
  var list=Array.prototype.slice.call(files), done=0, fail=0;
  mgStatus('importing '+list.length+' file'+(list.length===1?'':'s')+'…');
  function next(){
    if(!list.length){
      mgStatus('imported '+done+' file'+(done===1?'':'s')+(fail?(' · '+fail+' failed'):''),
               fail?'var(--warn)':'var(--good)');
      SX.cat='recorded'; SX.sel=null; SX.sort='new'; SX.dir=-1; SX.q=''; sxLoad(true);
      return;
    }
    var file=list.shift();
    var xhr=new XMLHttpRequest();
    xhr.open('POST','/inspect/api/merge/record?name='
             + encodeURIComponent(file.name.replace(/\.[^.]+$/,'')));
    xhr.onload=function(){ var d=null; try{ d=JSON.parse(xhr.responseText); }catch(e){}
      if(xhr.status===200 && d && d.ok) done++; else fail++;
      next(); };
    xhr.onerror=function(){ fail++; next(); };
    xhr.setRequestHeader('Content-Type', file.type||'application/octet-stream');
    xhr.send(file);
  }
  next();
}
function sxtLicence(){
  var it=sxtTarget(), r=SX.curRec;
  var rec = it ? (SX.all.filter(function(x){ return x.c===it.c && x.f===it.f; })[0]||null) : r;
  if(!rec){ mgStatus('play a sound, or select a layer, first','var(--warn)'); return; }
  var lic=rec.lic||rec.licence||rec.license||'(none recorded)';
  var att=rec.attribution||rec.attr||'';
  alert('Licence for '+(rec.n||rec.f)+'\n\n'
    + 'Library : '+sxCatLabel(rec.c)+'\n'
    + 'Licence : '+lic+'\n'
    + (att?('Credit  : '+att+'\n'):'')
    + (rec.src||rec.source?('Source  : '+(rec.src||rec.source)+'\n'):'')
    + '\nA merge inherits the STRICTEST licence of its sources, and an unclean '
    + 'source fails the whole merge closed at publish time.');
}

/* ── the analysis sheet ───────────────────────────────────────────────── */
function sxaClose(){ document.getElementById('sxa-modal').classList.remove('on'); }
function sxtAnalyze(focus){
  sxtWithTarget(function(it){
    var m=document.getElementById('sxa-modal');
    document.getElementById('sxa-sub').textContent=it.n+' · measuring…';
    document.getElementById('sxa-bd').innerHTML='<div class="sxa-note">Rendering the layer with its chain, then measuring it…</div>';
    m.classList.add('on');
    vsPost('/inspect/api/merge/analyze', {cat:it.c, f:it.f, slots:it.slots||[], pictures:true})
     .then(function(d){ sxaDraw(it, d, focus); })
     .catch(function(e){
       document.getElementById('sxa-bd').innerHTML='<div class="sxa-note" style="color:var(--bad)">'
         + esc('could not measure: '+(e.message||e))+'</div>'; });
  }, 'analysis');
}
function sxaNum(v, d){ return (v==null||isNaN(v))?'—':(+v).toFixed(d==null?2:d); }
function sxaDraw(it, d, focus){
  var s=d.stats||{}, src=d.source||{};
  document.getElementById('sxa-sub').textContent =
    it.n+' · '+((it.slots||[]).length)+' effect'+(((it.slots||[]).length)===1?'':'s')+' applied';
  var tp=s.true_peak, pk=s.peak_level;
  var clipCls = (tp!=null && tp>-0.1) ? 'bad' : (tp!=null && tp>-1) ? 'warn' : 'good';
  function cell(k,v,cls){ return '<div class="sxa-cell'+(cls?' '+cls:'')+'"><div class="k">'+esc(k)
    + '</div><div class="v">'+esc(String(v))+'</div></div>'; }
  var cells=[
    cell('Length', sxaNum(d.dur,3)+' s'),
    cell('Source length', sxaNum(d.src_dur,3)+' s'),
    cell('Peak', sxaNum(pk)+' dBFS', pk!=null&&pk>-0.1?'bad':''),
    cell('True peak', sxaNum(tp)+' dBTP', clipCls),
    cell('RMS', sxaNum(s.rms_level)+' dBFS'),
    cell('Crest factor', sxaNum(s.crest_factor)),
    cell('Loudness', sxaNum(s.lufs_i,1)+' LUFS'),
    cell('Loudness range', sxaNum(s.lra,1)+' LU'),
    cell('Dynamic range', sxaNum(s.dr!=null?s.dr:s.dynamic_range,1)),
    cell('DC offset', sxaNum(s.dc_offset,5)),
    cell('Flatness', sxaNum(s.flat_factor)),
    cell('Noise floor', sxaNum(s.noise_floor)+' dBFS'),
    cell('Zero crossings', sxaNum(s.zero_crossings_rate,4)),
    cell('Samples', s.number_of_samples!=null?Math.round(s.number_of_samples).toLocaleString():'—'),
    cell('Source codec', (src.codec||'—')+(src.sample_rate?(' · '+src.sample_rate+' Hz'):'')),
    cell('Source channels', src.channels||'—')
  ].join('');
  var sil=(s.silence||[]);
  var pics=d.pictures||{};
  var html='<div class="sxa-grid">'+cells+'</div>';
  if(pics.spectrogram) html+='<img class="sxa-img" src="'+esc(pics.spectrogram)+'" alt="spectrogram">';
  if(pics.waveform) html+='<img class="sxa-img" src="'+esc(pics.waveform)+'" alt="waveform">';
  html+='<div class="sxa-note">'
    + (tp!=null && tp>-0.1
        ? '<b style="color:var(--bad)">This layer is at or over 0 dBTP.</b> Put a Limiter or Normalize at the end of its chain. '
        : (tp!=null ? 'True peak is '+sxaNum(-tp)+' dB under full scale. ' : ''))
    + (sil.length ? ('Silence detector found '+Math.ceil(sil.length/2)+' quiet stretch'
        + (Math.ceil(sil.length/2)===1?'':'es')+' under −50 dB. ') : 'No stretch under −50 dB. ')
    + 'Every number here was measured on the layer AFTER its effect chain, not on the library file.'
    + '</div>';
  document.getElementById('sxa-bd').innerHTML=html;
  if(focus==='spectrogram'||focus==='waveform'){
    var img=document.querySelector('#sxa-bd img[alt="'+focus+'"]');
    if(img) img.scrollIntoView({block:'nearest'});
  }
}

/* ── the bars themselves ──────────────────────────────────────────────── */
function sxtBarsApply(){
  var col=document.getElementById('sxt-col'), dock=document.getElementById('sxt-dock');
  var arrow=document.getElementById('sxt-arrow');
  if(col) col.classList.toggle('hid', !SXT.bars);
  if(dock) dock.classList.toggle('off', !SXT.bars || !SXT.dock);
  if(arrow) arrow.innerHTML = SXT.bars ? '&#9654;' : '&#9664;';
  var grip=document.getElementById('sxt-grip'); if(grip) grip.classList.toggle('on', SXT.dock);
}
function sxtBarsToggle(){
  SXT.bars=!SXT.bars;
  try{ localStorage.setItem('sx.bars', SXT.bars?'1':'0'); }catch(e){}
  sxtBarsApply(); sxtRender();
}
function sxtDockToggle(){
  SXT.dock=!SXT.dock;
  try{ localStorage.setItem('sx.dock', SXT.dock?'1':'0'); }catch(e){}
  sxtBarsApply();
}
function sxtHelp(){
  var n=((MG.spec&&MG.spec.effect_types)||[]).length;
  alert('SFX STUDIO TOOLBOX\n\n'
   + 'RIGHT RAIL — '+n+' effects. Click one and it is APPENDED to the selected sound’s\n'
   + 'chain, with its knobs open. A dot on an icon means that effect is already on\n'
   + 'this sound. Sections: Core, Level, Tone, Time, Space, Modulation, Repair,\n'
   + 'Utility, Plugins (the notched ones are VST3).\n\n'
   + 'WHAT IT ACTS ON — the card selected on the board; if there is none, the sound\n'
   + 'you last played in the library, which is added to the board first.\n\n'
   + 'BOTTOM DOCK — transport, timeline, layer, chain, presets, measurement and\n'
   + 'library. Nothing is in both bars.\n\n'
   + 'CHAIN ORDER IS THE SIGNAL PATH. Effects run top to bottom in the mixer; drag\n'
   + 'order with the mixer’s right-click menu. Up to '+((MG.spec&&MG.spec.max_slots)||10)
   + ' per layer.\n\n'
   + 'A/B — Bypass empties the chain and puts it back. That is the only honest way\n'
   + 'to hear what your chain did.\n\n'
   + 'SAVING — "Save this layer" writes ONE edited sound back into the Merged\n'
   + 'library with a derived licence and a recipe that reopens it. "Save merge"\n'
   + 'writes the whole board. "Export" hands you a file and touches no library.\n\n'
   + 'MEASURE — every number is taken on the layer AFTER its chain, never on the\n'
   + 'library file.');
}


/* ══════════════════════════════════════════════════════════════════════════
   MUSIC STUDIO (2026-09-05) — the Sfx Studio tab, cloned.
   Library half (MUS/mus*), mixer (MMG/mmg*) and toolbox wiring (MST/mst*)
   are their source renamed, so every fix to one is one edit away from the
   other. What differs on purpose: the payload is filtered to the musical
   libraries, the 66k-row instruments library is asked for up front (it is
   DEFERRED server-side, so it ships no rows until a tab opens it), and the
   bars are driven by music_studio.py instead of by a table in this page.
   ═══════════════════════════════════════════════════════════════════════ */
var MUS = {loaded:false, cats:[], packs:[], all:[], cat:'', sel:null, q:'',
          /* `instruments` is DEFERRED server-side (66,028 rows, over
             _ALIB_DEFER_MIN): it is listed with its true count but ships no
             rows until a tab asks. This tab is that tab, so it asks up front —
             measured 21 MB, 9.0 s cold / 0.09 s warm, and ~130 ms of browser
             work once. */
          extra:['instruments'],
          clean:false, noverbal:false, sort:'pack', dir:1, facet:[], shown:[],
          cur:-1, curRec:null, playing:false, loop:false,
          busyT:null, pending:null,   /* the loading ring: its timer, and the library being fetched */
          open:{}};

function musEnter(){
  if(!MUS.loaded) musLoad(false);
  var r=MMG.reopen; MMG.reopen=null;
  if(r && r.uid) mmgMixerOpen(r.uid);
  /* 2026-09-02: the toolbox. The rail is built FROM the server's effect list,
     so it is drawn once the spec answers rather than from a second table here.
     A failed spec still draws the dock — the session tools do not need it. */
  try{ MST.bars = localStorage.getItem('mus.bars')!=='0';
       MST.dock = localStorage.getItem('mus.dock')!=='0';
       MST.clip = JSON.parse(localStorage.getItem('mus.chainclip')||'null'); }catch(e){}
  mstBarsApply(); mstRender();
  mstSpecLoad();                                  /* the 299-option roster */
  mmgSpec().then(mstRender).catch(function(){});  /* the effect rail */
}
/* 2026-09-01: the merger's dialogs deliberately live OUTSIDE the view div so a
   re-render cannot tear one down mid-edit — but that also meant they stayed on
   screen after a tab switch, floating over whatever tab you moved to. Leaving
   puts them away and remembers the mixer's target; coming back re-opens it on
   the same track. */
function mmgDialogsAway(){
  if(MMG.mixer) MMG.reopen={uid:MMG.mixer};
  mmgMixerClose(); mmgTwClose(); mmgTsClose(); mmgTkEditClose(); mmgMenuClose();
  mmgWait(false);
  var mq=document.getElementById('mmg-marq'); if(mq) mq.style.display='none';
}
function musLeave(){ var a=document.getElementById('mus-audio'); if(a && !a.paused) a.pause(); var m=document.getElementById('mmg-audio'); if(m && !m.paused) m.pause(); mmgDialogsAway(); }
function musUrl(r){ return '/inspect/sfx?cat='+encodeURIComponent(r.c)+'&f='+encodeURIComponent(r.f); }
function musCatLabel(c){ for(var i=0;i<MUS.cats.length;i++) if(MUS.cats[i].key===c) return MUS.cats[i].label; return c; }
function musFmtDur(d){
  if(!d) return '—';
  if(d<10) return d.toFixed(2)+' s';
  if(d<60) return d.toFixed(1)+' s';
  var m=Math.floor(d/60), s=Math.round(d-m*60); if(s===60){m++;s=0;}
  return m+':'+(s<10?'0':'')+s;
}
function musFmt(r){
  var p=[]; if(r.sr) p.push((r.sr%1000? (r.sr/1000).toFixed(1) : (r.sr/1000))+'k'+(r.bt?'/'+r.bt:''));
  if(r.ch) p.push(r.ch===1?'mono':r.ch===2?'stereo':r.ch+'ch');
  return p.join(' ');
}
function musCmp(a,b){ return String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'}); }

/* the ring that fills a rail with nothing drawn in it yet */
function musLoadingHtml(sub){
  return '<div class="mus-loading"><div class="ring"></div><div>Loading…</div>'
    + (sub?'<div class="sub">'+esc(sub)+'</div>':'') + '</div>';
}

/* the badge over a rail that still holds the PREVIOUS list. Raised on a
   250 ms delay: a cached answer comes back faster than that, and a ring that
   appears and vanishes inside a frame reads as a glitch, not as progress. */
function musBusy(on, label){
  clearTimeout(MUS.busyT); MUS.busyT=null;
  var el=document.getElementById('mus-busy'); if(!el) return;
  var bd=el.parentNode;
  if(!on){ el.classList.remove('on'); if(bd) bd.classList.remove('busy'); return; }
  var lb=el.querySelector('span:last-child');
  if(lb) lb.textContent=(label||'Loading')+'…';
  MUS.busyT=setTimeout(function(){ el.classList.add('on'); if(bd) bd.classList.add('busy'); }, 250);
}

function musLoad(force, silent){
  MUS.loaded = true;
  var rail=document.getElementById('mus-rail');
  /* nothing drawn yet -> the ring owns the rail; a list already drawn (opening
     a deferred library, a forced reload) -> the badge floats over it and what
     is on screen stays readable underneath */
  var blank = (force || !MUS.all.length);
  if(blank) rail.innerHTML=musLoadingHtml(MUS.all.length?'':'66,028 instrument one-shots');
  else if(!silent) musBusy(true, MUS.pending ? musCatLabel(MUS.pending) : 'Loading');
  var qs=[]; if(force) qs.push('force=1');
  if(MUS.extra.length) qs.push('extra='+encodeURIComponent(MUS.extra.join(',')));
  apiIf('/inspect/api/sfx'+(qs.length?'?'+qs.join('&'):''), 'mus', force).then(function(d){
    musBusy(false); MUS.pending=null;
    if(d===NOCHANGE) return;          /* library unchanged: keep the rendered rail */
    if(d.error){ rail.innerHTML='<div class="vid-empty" style="padding:30px 10px;font-size:.78rem;color:var(--bad)">'+esc(d.error)+'</div>'; return; }
    MUS.cats=d.categories||[]; MUS.packs=d.packs||[]; MUS.all=d.files||[];
    /* 2026-09-05: this tab is the MUSICAL half of the same payload. The
       endpoint answers every audio library (the Sfx Studio wants them all);
       Music Studio keeps the instruments, the music cues, and the two
       categories its own saves land in — a tab that can save into Merged but
       cannot see Merged could not reopen its own recipe. The list comes from
       music_studio.py so it is not stated twice. */
    var allow=(MST.spec&&MST.spec.categories)||MUS_CATS_FALLBACK;
    MUS.cats=MUS.cats.filter(function(c){ return allow.indexOf(c.key)>=0; });
    MUS.all=MUS.all.filter(function(r){ return allow.indexOf(r.c)>=0; });
    var order={}; MUS.cats.forEach(function(c,i){ order[c.key]=i; });
    MUS.all.forEach(function(r,i){
      r.i=i; r.pl=MUS.packs[r.p]||''; r.co=order[r.c]||0;
      r.k=(r.n+' '+r.f+' '+r.g+' '+r.pl+' '+(r.u||'')+' '+(r.vt||'')+' '+r.c).toLowerCase();
    });
    /* the file that was playing keeps playing; re-find it so the highlight
       and ↑/↓ still know where it is after a refresh */
    if(MUS.curRec){ var cr=MUS.curRec; MUS.curRec=null;
      for(var j=0;j<MUS.all.length;j++){ if(MUS.all[j].c===cr.c && MUS.all[j].f===cr.f){ MUS.curRec=MUS.all[j]; break; } } }
    if(MUS.cat && !MUS.cats.some(function(c){return c.key===MUS.cat;})) MUS.cat='';
    musRender();
    mmgRestore();     // a merge list survives a reload; needs the records to exist
  }).catch(function(e){ musBusy(false); MUS.pending=null;
      rail.innerHTML='<div class="vid-empty" style="color:var(--bad)">Failed to load the instrument library ('+esc(e.message||e)+').</div>'; });
}

/* ── filters ── */
function musIsDeferred(k){
  for(var i=0;i<MUS.cats.length;i++) if(MUS.cats[i].key===k) return !!MUS.cats[i].deferred;
  return false;
}
function musSetCat(k){
  /* opening a deferred library fetches it first — one reload, then it behaves
     like any other category for the rest of the session */
  if(k && MUS.cat!==k && musIsDeferred(k)){
    if(MUS.extra.indexOf(k)<0) MUS.extra.push(k);
    MUS.cat=k; MUS.sel=null; MUS.pending=k; musLoad(false); return;
  }
  MUS.cat=(MUS.cat===k?'':k); MUS.sel=null; musRender();
}
function musSetQuery(v){ MUS.q=(v||'').trim().toLowerCase(); musRender(); }
function musToggle(k){
  MUS[k]=!MUS[k]; musRender();
}
function musSort(k){
  if(MUS.sort===k) MUS.dir=-MUS.dir; else { MUS.sort=k; MUS.dir=(k==='dur'||k==='new')?-1:1; }
  musRender();
}
function musSortFn(){
  var s=MUS.sort, dir=MUS.dir;
  return function(a,b){
    var r=0;
    if(s==='name') r=musCmp(a.n,b.n);
    else if(s==='group') r=musCmp(a.g,b.g)||musCmp(a.n,b.n);
    else if(s==='dur') r=(a.d||0)-(b.d||0);
    else if(s==='new') r=(a.m||0)-(b.m||0);
    else if(s==='fmt') r=(a.sr||0)-(b.sr||0)||(a.ch||0)-(b.ch||0);
    if(!r) r=(a.co-b.co)||musCmp(a.pl,b.pl)||musCmp(a.g,b.g)||musCmp(a.n,b.n)||musCmp(a.f,b.f);
    return dir*r;
  };
}

/* ── render ── */
function musRender(){
  var q=MUS.q, sel=MUS.sel;
  /* facet = everything but the tree selection, so the tree can show counts
     for what the search + toggles leave */
  MUS.facet = MUS.all.filter(function(r){
    if(MUS.cat && r.c!==MUS.cat) return false;
    if(MUS.clean && r.t!=='model') return false;
    if(MUS.noverbal && r.v) return false;
    if(q && r.k.indexOf(q)<0) return false;
    return true;
  });
  MUS.shown = !sel ? MUS.facet.slice() : MUS.facet.filter(function(r){
    if(r.c!==sel.c || r.p!==sel.p) return false;
    if(sel.g!==null && r.g!==sel.g) return false;
    return true;
  });
  MUS.shown.sort(musSortFn());
  MUS.cur = MUS.curRec ? MUS.shown.indexOf(MUS.curRec) : -1;

  /* 2026-08-25: the sample count and the library / search / licence bar were
     taken out of the header — the rail already carries the same library tree
     with the same counts, so the numbers were said twice. Both are written
     through if-present, so putting either back is a markup change alone. */
  var cn=document.getElementById('mus-count');
  if(cn){
    var base=MUS.cat ? MUS.all.filter(function(r){return r.c===MUS.cat;}).length : MUS.all.length;
    cn.textContent = MUS.shown.length.toLocaleString()+' of '+base.toLocaleString()+' sample'+(base===1?'':'s')
      + (MUS.cat ? ' in '+musCatLabel(MUS.cat) : ' across '+MUS.cats.length+' libraries');
  }
  var bar=document.getElementById('mus-bar');
  if(bar){
    /* chips: one per library, with its total — the library's job in the title */
    var chips = MUS.cats.map(function(c){
      var dt = c.deferred ? ' — click to load (kept out of the default payload: '+c.count.toLocaleString()+' rows)' : '';
      return '<button class="vchip'+(MUS.cat===c.key?' on':'')+'" title="'+esc((c.desc||'')+dt)+'" onclick="musSetCat(\''+esc(c.key)+'\')">'
        + esc(c.label)+'<span class="n">'+c.count.toLocaleString()+(c.deferred?'&nbsp;&#8595;':'')+'</span></button>';
    }).join('');
    bar.innerHTML =
      (MUS.cat?'<button class="vchip on" onclick="musSetCat(\''+esc(MUS.cat)+'\')">&times; all libraries</button>':'')
      + chips
      + '<input type="search" placeholder="search name, file, group, pack, UCS…" value="'+esc(MUS.q)+'" oninput="musSetQuery(this.value)">'
      + '<label class="tg" title="Only CC0 / own-recording files that may feed a voice or a model — every vendor pack is mix-only">'
      + '<input type="checkbox"'+(MUS.clean?' checked':'')+' onchange="musToggle(\'clean\')"> model-clean only</label>'
      + '<label class="tg" title="Hide files Whisper heard real words in (\'help\', \'can anybody hear me\')">'
      + '<input type="checkbox"'+(MUS.noverbal?' checked':'')+' onchange="musToggle(\'noverbal\')"> hide verbal</label>';
  }

  musRenderRail();
}

/* file leaves are rendered inline in the rail, nested under whichever
   pack/group is currently selected — MUS.shown is already narrowed to exactly
   that selection (see the filter above), so it can be used as-is. Capped so a
   huge pack doesn't dump thousands of rows into a 310px column at once. */
var MUS_FCAP = 400;

function musFileLeafHtml(r, idx){
  var cur=(r===MUS.curRec);
  return '<div class="mus-file'+(cur?' on':'')+(cur&&MUS.playing?' playing':'')+'" data-i="'+idx+'"'
    + ' title="'+esc(r.f)+(r.u?' · '+esc(r.u):'')+'">'
    + '<span class="pb">'+(cur&&MUS.playing?'&#10074;&#10074;':'&#9654;')+'</span>'
    + '<span class="lb">'+esc(r.n)+'</span>'
    + '<span class="du">'+musFmtDur(r.d)+'</span></div>';
}

function musFileLeavesHtml(){
  var rows=MUS.shown, n=rows.length;
  if(!n) return '<div class="mus-more" style="padding:6px 8px 6px 40px;text-align:left">Nothing matches this filter.</div>';
  var h='<div class="mus-files">', to=Math.min(n, MUS_FCAP);
  for(var i=0;i<to;i++) h+=musFileLeafHtml(rows[i], i);
  if(to<n) h+='<div class="mus-more" style="padding:4px 8px 6px 40px;text-align:left">+'+(n-to).toLocaleString()+' more — narrow with search</div>';
  return h+'</div>';
}

function musRenderRail(){
  var rail=document.getElementById('mus-rail'), sel=MUS.sel;
  /* library → pack → group counts from the facet (search/toggle-filtered) */
  var tree={};
  MUS.facet.forEach(function(r){
    var c=tree[r.c]||(tree[r.c]={n:0,packs:{}}); c.n++;
    var p=c.packs[r.p]||(c.packs[r.p]={n:0,groups:{}}); p.n++;
    p.groups[r.g]=(p.groups[r.g]||0)+1;
  });
  var html='';
  MUS.cats.forEach(function(c){
    if(MUS.cat && c.key!==MUS.cat) return;
    var t=tree[c.key];
    if(!t && c.deferred){
      /* listed with its true count, rows not shipped yet — one click loads it */
      html += '<h4 onclick="musSetCat(\''+esc(c.key)+'\')" title="'+esc(c.desc||'')+'">'
        + esc(c.label)+'<span class="n">'+c.count.toLocaleString()+'</span></h4>'
        + '<div class="mus-grp" style="cursor:pointer" onclick="musSetCat(\''+esc(c.key)+'\')">'
        + '<span class="lb"><i>'+c.count.toLocaleString()+' samples — click to load this library</i></span></div>';
      return;
    }
    if(!t){
      /* the merged library is a destination before it is a source: show it even while it is empty */
      if(c.key==='merged' && !MUS.q && !MUS.clean && !MUS.noverbal)
        html += '<h4 class="'+(MUS.cat===c.key?'on':'')+'" onclick="musSetCat(\''+esc(c.key)+'\')" title="'+esc(c.desc||'')+'">'
          + esc(c.label)+'<span class="n">0</span></h4>'
          + '<div class="mus-grp" style="cursor:default;opacity:.7"><span class="lb"><i>nothing saved yet — right-click an instrument → Add as a track, then &#128190; save</i></span></div>';
      return;
    }
    html += '<h4 class="'+(MUS.cat===c.key?'on':'')+'" onclick="musSetCat(\''+esc(c.key)+'\')" title="'+esc(c.desc||'')+'">'
      + esc(c.label)+'<span class="n">'+t.n.toLocaleString()+'</span></h4>';
    Object.keys(t.packs).map(Number).sort(function(a,b){ return musCmp(MUS.packs[a],MUS.packs[b]); }).forEach(function(p){
      var pk=t.packs[p], key=c.key+'|'+p;
      var selP = sel && sel.c===c.key && sel.p===p;
      var selPAll = selP && sel.g===null;
      var open = selP || MUS.open[key];
      var gkeys=Object.keys(pk.groups);
      html += '<div class="mus-pack'+(selPAll?' on':'')+'" data-c="'+esc(c.key)+'" data-p="'+p+'">'
        + '<span class="tw" data-tw="'+esc(key)+'">'+(gkeys.length>1?(open?'&#9662;':'&#9656;'):'&middot;')+'</span>'
        + '<span class="lb" title="'+esc(MUS.packs[p])+'">'+esc(MUS.packs[p])+'</span><span class="n">'+pk.n.toLocaleString()+'</span></div>';
      if(selPAll) html += musFileLeavesHtml();
      if(open && gkeys.length>1){
        gkeys.sort(musCmp).forEach(function(g){
          var on = selP && sel.g===g;
          html += '<div class="mus-grp'+(on?' on':'')+'" data-c="'+esc(c.key)+'" data-p="'+p+'" data-g="'+esc(g)+'">'
            + '<span class="lb">'+(g?esc(g):'<i>(ungrouped)</i>')+'</span><span class="n">'+pk.groups[g].toLocaleString()+'</span></div>';
          if(on) html += musFileLeavesHtml();
        });
      }
    });
  });
  rail.innerHTML = html || '<div class="vid-empty" style="padding:30px 10px;font-size:.78rem">Nothing here.</div>';
}

/* ── clicks: delegated, one listener per pane ── */
document.getElementById('mus-rail').addEventListener('click', function(e){
  var file=e.target.closest ? e.target.closest('.mus-file') : null;
  if(file){
    if(window.MMG && MMG.sel) mmgSelect(null);   // the rail has the keys again (space / delete)
    musPlayIdx(+file.getAttribute('data-i'));
    return;
  }
  var tw=e.target.closest ? e.target.closest('[data-tw]') : null;
  if(tw){ /* twisty: expand/collapse only */
    e.stopPropagation(); var k=tw.getAttribute('data-tw'); MUS.open[k]=!MUS.open[k]; musRenderRail(); return;
  }
  var el=e.target.closest ? e.target.closest('[data-p]') : null;
  if(!el) return;
  var c=el.getAttribute('data-c'), p=+el.getAttribute('data-p');
  var g=el.hasAttribute('data-g') ? el.getAttribute('data-g') : null;
  var same = MUS.sel && MUS.sel.c===c && MUS.sel.p===p && MUS.sel.g===g;
  MUS.sel = same ? null : {c:c, p:p, g:g};
  if(!same) MUS.open[c+'|'+p]=true;
  musRender();
});

/* ── playback ── */
function musPlayIdx(i){ var r=MUS.shown[i]; if(r) musPlay(r,i); }
function musPlay(r,i){
  var a=document.getElementById('mus-audio');
  if(r===MUS.curRec){       /* the playing row toggles pause, like its glyph says */
    if(a.paused) a.play().catch(function(){}); else a.pause();
    return;
  }
  MUS.curRec=r; MUS.cur=i;
  a.loop=MUS.loop; a.src=musUrl(r); a.play().catch(function(){});
  musMarkRow();
}
function musMarkRow(){
  var rail=document.getElementById('mus-rail');
  Array.prototype.forEach.call(rail.querySelectorAll('.mus-file.on'), function(el){
    el.classList.remove('on','playing'); el.querySelector('.pb').innerHTML='&#9654;';
  });
  if(MUS.cur<0) return;
  var el=rail.querySelector('.mus-file[data-i="'+MUS.cur+'"]');
  if(!el) return;
  el.classList.add('on'); el.classList.toggle('playing',MUS.playing);
  el.querySelector('.pb').innerHTML = MUS.playing ? '&#10074;&#10074;' : '&#9654;';
}
function musStep(dir){
  if(!MUS.shown.length) return;
  var i = MUS.cur<0 ? (dir>0?0:MUS.shown.length-1) : MUS.cur+dir;
  if(i<0 || i>=MUS.shown.length) return;
  musPlay(MUS.shown[i], i);
  var el=document.querySelector('#mus-rail .mus-file[data-i="'+i+'"]');
  if(el && el.scrollIntoView) el.scrollIntoView({block:'nearest'});
}
function musStop(){
  var a=document.getElementById('mus-audio');
  a.pause(); a.removeAttribute('src'); a.load();
  MUS.curRec=null; MUS.cur=-1; MUS.playing=false;
  musMarkRow();
}
(function(){
  var a=document.getElementById('mus-audio');
  a.addEventListener('play', function(){ MUS.playing=true; musMarkRow();
    var m=document.getElementById('mmg-audio'); if(m && !m.paused) m.pause(); });   // one thing plays at a time
  a.addEventListener('pause', function(){ MUS.playing=false; musMarkRow(); });
  /* 2026-09-01c: a finished sample STOPS. It used to chain into the next row
     (musStep(1)) unless loop was on, which meant walking away from one click
     played the rest of the pack — with 2,800 samples in a list that is not a
     preview, it is a queue nobody asked for. ↑/↓ still step deliberately. */
  a.addEventListener('ended', function(){ MUS.playing=false; musMarkRow(); });
  a.addEventListener('error', function(){
    MUS.playing=false; musMarkRow();
    if(MUS.curRec) console.warn('Could not load '+MUS.curRec.f);
  });
})();
/* keys: only while the tab is showing and focus is not in a field or the
   player's own controls (which handle space natively) */
document.addEventListener('keydown', function(e){
  var v=document.getElementById('view-musicstudio'); if(!v || v.style.display!=='flex') return;
  var t=e.target, tn=t&&t.tagName;
  if(tn==='INPUT'||tn==='SELECT'||tn==='TEXTAREA'||tn==='AUDIO'){ if(e.key==='Escape') t.blur(); return; }
  if(mmgKey(e)) return;      // the merger owns ←/→/Delete (and space/esc while a card is selected)
  if(e.key==='ArrowDown'){ e.preventDefault(); musStep(1); }
  else if(e.key==='ArrowUp'){ e.preventDefault(); musStep(-1); }
  else if(e.key===' '){
    e.preventDefault(); var a=document.getElementById('mus-audio');
    if(!MUS.curRec) musStep(1); else if(a.paused) a.play().catch(function(){}); else a.pause();
  }
  else if(e.key==='Escape'){ musStop(); }
});


/* ── the mixer: the Sfx Merger, renamed. Layers on one ms-precise ruler,
     one cached stem per (file, knobs) and one cached mix per (stems,
     starts) on the server — see sfx_merger.py. ── */
var MMG = {items:[], loop:false, zoom:110, mix:null, mixDirty:false, seq:0, inflight:false, pending:null,
          sel:null, selIds:[], spec:null, tw:null, twSlot:null, twMode:'solo', twTimer:null, twSeq:0, ts:null, tked:null, mixer:null, shown:false,
          playing:false, stemPlaying:false, headBase:0, raf:0, waves:{}, actx:null, restored:false,
          laneH:46, lastName:'', menuFns:[], waitT:0, nudgeT:0, wGain:null, dragging:false, stemBusy:false, stemPending:false, waveByUid:{},
          recDevice:'', recDeviceLabel:'', recStream:null, recRecorder:null, recChunks:[]};
var MMG_ZOOMS=[16,26,40,60,85,110,150,210,300,420,600,850,1200,1700,2400,3400,4800];

function mmgUid(){ return 'i'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
function mmgFmt(t){ t=Math.max(0,+t||0); if(t<60) return t.toFixed(3)+' s';
  var m=Math.floor(t/60), r=t-m*60; return m+':'+(r<10?'0':'')+r.toFixed(3); }
function mmgFmtMs(t){ return mmgFmt(t)+' · '+Math.round(Math.max(0,+t||0)*1000).toLocaleString()+' ms'; }
/* "1.25" · "1,25" · "1250ms" · "0:01.250" · "1m2.5s" → seconds (NaN if not a time) */
function mmgParseT(v){
  v=String(v==null?'':v).trim().toLowerCase().replace(/,/g,'.').replace(/\s+/g,'');
  if(!v) return NaN;
  var m;
  if((m=v.match(/^(\d+(?:\.\d+)?)ms$/))) return +m[1]/1000;
  if((m=v.match(/^(\d+):(\d+(?:\.\d+)?)$/))) return +m[1]*60+ +m[2];
  if((m=v.match(/^(\d+)m(\d+(?:\.\d+)?)s?$/))) return +m[1]*60+ +m[2];
  if((m=v.match(/^(\d+(?:\.\d+)?)s?$/))) return +m[1];
  return NaN;
}
function mmgAudio(){ return document.getElementById('mmg-audio'); }
function mmgItem(uid){ for(var i=0;i<MMG.items.length;i++) if(MMG.items[i].uid===uid) return MMG.items[i]; return null; }
function mmgFind(c,f){ return MMG.items.filter(function(i){ return i.c===c && i.f===f; }); }
function mmgTotal(){ var t=0; MMG.items.forEach(function(i){ t=Math.max(t, i.start+(i.dur||0)); }); return t; }
function mmgRacksFor(typ){                     /* a plugin effect type owns its own knob set —
   fall back to the Tweaker's own global racks for 'tweak' and for anything not (yet) loaded */
  if(typ && typ!=='tweak' && MMG.spec){ var et=mmgEffectType(typ); if(et && et.racks) return et.racks; }
  return MMG.spec ? MMG.spec.racks : null; }
function mmgParam(k, typ){ var rs=mmgRacksFor(typ); if(!rs) return null; for(var i=0;i<rs.length;i++)
  for(var j=0;j<rs[i].params.length;j++) if(rs[i].params[j].key===k) return rs[i].params[j]; return null; }
function mmgDefaults(typ){
  if(!typ || typ==='tweak') return MMG.spec ? JSON.parse(JSON.stringify(MMG.spec.defaults)) : {};
  var rs=mmgRacksFor(typ); if(!rs) return {};
  var d={}; rs.forEach(function(r){ r.params.forEach(function(p){ d[p.key]=p.def; }); }); return d; }
function mmgIsDefault(t, typ){ if(!MMG.spec||!t) return true; var d=mmgDefaults(typ);
  for(var k in d){ if(!d.hasOwnProperty(k)) continue; var p=mmgParam(k, typ); if(!p) continue;
    if(p.type==='toggle'){ if(!!t[k]!==!!d[k]) return false; } else if(Math.abs((+t[k])-(+d[k]))>1e-9) return false; }
  return true; }
function mmgSpec(){ if(MMG.spec) return Promise.resolve(MMG.spec);
  return api('/inspect/api/merge/spec').then(function(d){ if(d.error) throw new Error(d.error); MMG.spec=d; return d; }); }
function mmgStatus(msg,col){ var s=document.getElementById('mmg-status'); s.textContent=msg||''; s.style.color=col||'var(--muted)'; }
function mmgWait(on){
  clearTimeout(MMG.waitT); var w=document.getElementById('mmg-wait');
  if(on){ MMG.waitT=setTimeout(function(){ w.classList.add('on'); }, 140); }   // only when it actually takes time
  else w.classList.remove('on');
}
function mmgShow(){ MMG.shown=true; var pn=document.getElementById('mmg-panel'); pn.style.display='flex';
  document.getElementById('mus-mmgbtn').style.display='none'; mmgPersist(); }
function mmgHide(){ MMG.shown=false; document.getElementById('mmg-panel').style.display='none';
  var b=document.getElementById('mus-mmgbtn'); b.style.display='';
  b.innerHTML='&#9881; Mixer'+(MMG.items.length?' ('+MMG.items.length+')':''); mmgPersist(); }
window.addEventListener('resize', function(){ if(MMG.shown) mmgWavesRedraw(); });

/* ── the list ── */
function mmgAdd(rec, o){
  o=o||{};
  mmgSpec().then(function(){
    var cap=(MMG.spec&&MMG.spec.max_items)||40;
    if(MMG.items.length>=cap){ mmgShow(); mmgStatus('the mixer takes at most '+cap+' tracks','var(--warn)'); alert('The mixer takes at most '+cap+' tracks.'); return; }
    var it={uid:mmgUid(), c:rec.c, f:rec.f, n:rec.n, d:rec.d||0, start:o.start||0,
            slots:o.slots||[], dur:rec.d||0, stem:'', url:'', label:'', color:'', muted:false, hideName:false};
    MMG.items.push(it);           // not auto-selected: the keys stay with the sample list until a card is clicked
    mmgShow(); mmgRenderBoard(); mmgPersist();
    mmgRender({why:'add', play:true, from:0, then:o.then});
  }).catch(function(e){ alert('Mixer unavailable: '+(e.message||e)); });
}
function mmgRemove(uid){
  var it=mmgItem(uid); if(!it) return;
  MMG.items=MMG.items.filter(function(i){ return i.uid!==uid; });
  MMG.selIds=MMG.selIds.filter(function(u){ return u!==uid; });
  if(MMG.sel===uid) MMG.sel=MMG.selIds.length?MMG.selIds[MMG.selIds.length-1]:null;
  if(MMG.tw===uid) mmgTwClose();
  if(MMG.ts===uid) mmgTsClose();
  if(MMG.tked===uid) mmgTkEditClose();
  if(MMG.mixer===uid) mmgMixerClose();
  /* its stem must not keep looping with no card on the board */
  if(MMG.stemPlaying && it.url && mmgAudio().getAttribute('data-src')===it.url) mmgStop(true);
  mmgRenderBoard(); mmgPersist();
  if(MMG.items.length) mmgRender({why:'remove', play:false, from:0});
  else mmgEmptied('no tracks');
}
/* the list is empty: drop whatever render is still in flight so it cannot
   load a ghost mix, and forget the old one */
function mmgEmptied(msg){
  MMG.seq++; MMG.pending=null; mmgWait(false);
  mmgStop(true); MMG.mix=null; MMG.mixDirty=false; mmgStatus(msg||''); mmgRenderBoard();
}
function mmgRemoveFile(c,f){ mmgFind(c,f).map(function(i){ return i.uid; }).forEach(mmgRemove); }
/* a rubber-band selection is removed in ONE pass: mmgRemove() per card would fire
   an ffmpeg render for every intermediate list on the way down */
function mmgRemoveMany(uids){
  var kill={}; uids.forEach(function(u){ kill[u]=1; });
  if(!MMG.items.some(function(i){ return kill[i.uid]; })) return;
  MMG.items=MMG.items.filter(function(i){ return !kill[i.uid]; });
  MMG.selIds=MMG.selIds.filter(function(u){ return !kill[u]; });
  if(kill[MMG.sel]) MMG.sel=MMG.selIds.length?MMG.selIds[MMG.selIds.length-1]:null;
  if(MMG.tw && kill[MMG.tw]) mmgTwClose();
  if(MMG.ts && kill[MMG.ts]) mmgTsClose();
  if(MMG.tked && kill[MMG.tked]) mmgTkEditClose();
  if(MMG.mixer && kill[MMG.mixer]) mmgMixerClose();
  if(MMG.stemPlaying) mmgStop(true);          // the stem it was auditioning may be gone
  mmgRenderBoard(); mmgPersist();
  if(MMG.items.length) mmgRender({why:'remove', play:false, from:0});
  else mmgEmptied('no tracks');
}
function mmgClear(){
  if(!MMG.items.length) return;
  if(!confirm('Remove every track ('+MMG.items.length+')?')) return;
  MMG.items=[]; MMG.sel=null; MMG.selIds=[]; mmgTwClose(); mmgTsClose(); mmgTkEditClose(); mmgMixerClose(); mmgPersist(); mmgEmptied('');
}

/* ── render (server) ──
   One request in flight at a time; anything that changes meanwhile is folded
   into ONE follow-up render of the latest state, so a fast drag or a knob sweep
   never queues thirty ffmpeg runs. */
function mmgSig(){ return JSON.stringify(MMG.items.map(function(i){ return [i.uid,i.c,i.f,i.start,i.slots,i.muted]; })); }
function mmgRender(o){
  o=o||{};
  if(MMG.inflight){
    var p=MMG.pending||{};
    MMG.pending={why:(o.why==='add'||p.why==='add')?'add':o.why, play:!!(o.play||p.play),
                /* the position to play from belongs to whoever asked to PLAY */
                from:(o.play ? o.from : (p.play ? p.from : (o.from!=null?o.from:p.from))), then:o.then||p.then};
    return;
  }
  if(!MMG.items.length) return;
  var live=MMG.items.filter(function(i){ return !i.muted; });
  if(!live.length){ mmgStop(true); MMG.mix=null; MMG.mixDirty=false; mmgStatus('every layer is muted','var(--warn)'); mmgRenderBoard(); return; }
  MMG.inflight=true; var seq=++MMG.seq, sig=mmgSig();
  if(o.why==='add') mmgWait(true);
  mmgStatus('rendering…');
  var items=live.map(function(i){ return {uid:i.uid, cat:i.c, f:i.f, name:i.n, start:i.start, slots:i.slots}; });
  vsPost('/inspect/api/merge/render',{items:items}).then(function(d){
    if(seq!==MMG.seq) return;                       // cancelled (the list was emptied)
    if(mmgSig()!==sig){ MMG.mixDirty=true; return; }  // the list changed while ffmpeg ran: stale — whoever changed it has queued a render or dirtied the mix
    MMG.mix=d; MMG.mixDirty=false;
    d.items.forEach(function(s){ var it=mmgItem(s.uid); if(it){ it.dur=s.dur; it.stem=s.stem; it.url=s.url; } });
    mmgRenderBoard(); mmgPersist();
    mmgStatus(mmgFmt(d.duration)+(d.scale<1?' · peak-scaled ×'+d.scale.toFixed(2):''));
    if(o.play) mmgPlay(o.from||0);
    else if(MMG.playing && !MMG.stemPlaying) mmgPlay(o.from!=null?o.from:mmgAudio().currentTime);  // keep the loop going on the new mix
    if(typeof o.then==='function') o.then(d);
  }).catch(function(e){
    mmgStatus('render failed', 'var(--bad)'); alert('Mix render failed: '+(e.message||e));
  }).then(function(){
    MMG.inflight=false;
    var p=MMG.pending; MMG.pending=null;
    if(p){ if(p.why!=='add') mmgWait(false); mmgRender(p); }
    else { mmgWait(false); if(MMG.tw && MMG.twMode==='mix') mmgTwStatus(MMG.mixDirty?'in the mix · not rendered yet':'in the mix'); }
  });
}

/* ── playback ── */
function mmgPauseSample(){ var mus=document.getElementById('mus-audio'); if(mus && !mus.paused) mus.pause(); }
function mmgPlayUrl(url, from, stem){
  var a=mmgAudio(); if(!url) return;
  mmgPauseSample();
  MMG.stemPlaying=!!stem; a.loop=MMG.loop;
  var want=Math.max(0, from||0);
  if(a.getAttribute('data-src')!==url){
    a.setAttribute('data-src',url); a.src=url;
    var go=function(){ a.removeEventListener('loadedmetadata',go);
      try{ if(want>0.0005) a.currentTime=Math.min(want, Math.max(0,(a.duration||0)-0.01)); }catch(err){}
      a.play().catch(function(){}); };
    a.addEventListener('loadedmetadata',go); a.load();
  } else {
    try{ a.currentTime=Math.min(want, Math.max(0,(a.duration||0)-0.01)); }catch(err){}
    a.play().catch(function(){});
  }
}
function mmgPlay(from){ if(MMG.mix && MMG.mix.url){ MMG.headBase=0; mmgPlayUrl(MMG.mix.url, from, false); } }
function mmgTogglePlay(){
  var a=mmgAudio();
  if(!MMG.items.length) return;
  if(!MMG.mix || !MMG.mix.url || MMG.mixDirty){ mmgRender({why:'play', play:true, from:0}); return; }
  if(a.getAttribute('data-src')!==MMG.mix.url){ mmgPlay(0); return; }   // a stem (or nothing) is loaded — never resume that as "the merge"
  if(a.paused){ mmgPauseSample(); if(a.ended || a.currentTime>=(a.duration||0)-0.005){ try{ a.currentTime=0; }catch(e){} } a.play().catch(function(){}); }
  else a.pause();
}
function mmgStop(silent){
  var a=mmgAudio(); a.pause(); try{ a.currentTime=0; }catch(e){}
  MMG.stemPlaying=false; mmgHeadDraw();
}
function mmgReplay(){
  if(!MMG.items.length) return;
  if(!MMG.mix || !MMG.mix.url || MMG.mixDirty){ mmgRender({why:'replay', play:true, from:0}); return; }
  mmgPlay(0);
}
function mmgToggleLoop(){
  MMG.loop=!MMG.loop; mmgAudio().loop=MMG.loop;
  document.getElementById('mmg-loop').classList.toggle('on',MMG.loop); mmgPersist();
}
function mmgHeadMark(){ if(!MMG.hm){ MMG.hm=document.createElement('div'); MMG.hm.className='hm'; MMG.hm.id='mmg-hm'; } return MMG.hm; }
function mmgHeadDraw(){
  var a=mmgAudio(), h=document.getElementById('mmg-head'), hm=mmgHeadMark();
  var has = !!(MMG.mix && MMG.mix.url) || MMG.stemPlaying;
  h.style.display = has ? 'block' : 'none'; hm.style.display = has ? 'block' : 'none';
  var t=(MMG.headBase||0)+(a.currentTime||0);
  h.style.left=(t*MMG.zoom).toFixed(1)+'px'; hm.style.left=(t*MMG.zoom).toFixed(1)+'px';
  document.getElementById('mmg-time').textContent = mmgFmt(t)+' / '+mmgFmt(MMG.mix?MMG.mix.duration:mmgTotal());
  var b=document.getElementById('mmg-play');
  b.innerHTML = (MMG.playing && !MMG.stemPlaying) ? '&#10074;&#10074;' : '&#9654;';
  b.classList.toggle('on', MMG.playing && !MMG.stemPlaying);
}
(function(){
  var a=mmgAudio();
  function tick(){ mmgHeadDraw(); if(MMG.playing) MMG.raf=requestAnimationFrame(tick); }
  a.addEventListener('play', function(){ MMG.playing=true; cancelAnimationFrame(MMG.raf); tick(); });
  a.addEventListener('pause', function(){ MMG.playing=false; cancelAnimationFrame(MMG.raf); mmgHeadDraw(); });
  a.addEventListener('ended', function(){ MMG.playing=false; cancelAnimationFrame(MMG.raf); mmgHeadDraw(); });
  a.addEventListener('error', function(){ MMG.playing=false; mmgStatus('could not load the mix','var(--bad)'); });
})();

/* ── the board: chips + ruler + lanes ── */
function mmgTickStep(){
  var st=[0.001,0.002,0.005,0.01,0.02,0.05,0.1,0.2,0.5,1,2,5,10,15,30,60];
  for(var i=0;i<st.length;i++) if(st[i]*MMG.zoom>=70) return st[i];
  return 60;
}
function mmgRenderBoard(){
  MMG.wGain=null;                       // layer set changed: re-solve the shared wave scale
  if(MMG.dragging){ MMG.rebuild=true; return; }   // a rebuild would detach the captured card mid-drag
  var n=MMG.items.length;
  document.getElementById('mmg-count').textContent =
    n ? (n+' track'+(n===1?'':'s')+' · '+mmgFmt(mmgTotal())) : 'no tracks';
  document.getElementById('mmg-save').disabled = !n;
  document.getElementById('mmg-loop').classList.toggle('on',MMG.loop);
  /* the button is the ONLY way back once the board is folded away, so it shows
     whenever the board is hidden — item count has nothing to do with it. */
  var b=document.getElementById('mus-mmgbtn');
  if(!MMG.shown){ b.style.display=''; b.innerHTML='&#9881; Mixer'+(n?' ('+n+')':''); }
  mmgSelInfo();
  /* ruler + lanes */
  var total=mmgTotal(), span=Math.max(total*1.08+0.5, 3), W=Math.ceil(span*MMG.zoom)+60;
  var canvas=document.getElementById('mmg-canvas'); canvas.style.width=W+'px';
  var step=mmgTickStep(), minor=step/5, h='';
  if(minor*MMG.zoom<7) minor=step/2;
  if(minor*MMG.zoom<7) minor=step;
  var lastLab=-1e9;
  for(var t=0; t<=span+1e-9; t=+(t+minor).toFixed(6)){
    var x=t*MMG.zoom, mj=Math.abs(t/step-Math.round(t/step))<1e-6;
    h+='<div class="tk'+(mj?' mj':'')+'" style="left:'+x.toFixed(2)+'px"></div>';
    if(mj && x-lastLab>=60){ h+='<div class="tl'+(t===0?' t0':'')+'" style="left:'+x.toFixed(2)+'px">'+(t<60?t.toFixed(3):mmgFmt(t))+'</div>'; lastLab=x; }
  }
  /* the hover label and the playhead marker ride INSIDE the sticky ruler, so
     they stay visible however far the lanes are scrolled — grab them BEFORE the
     innerHTML reset destroys the previous ruler's children */
  var ruler=document.getElementById('mmg-ruler'), hvl=document.getElementById('mmg-hvl'), hm=mmgHeadMark();
  ruler.innerHTML=h; ruler.appendChild(hvl); ruler.appendChild(hm);
  var lanes=document.getElementById('mmg-lanes');
  lanes.style.backgroundSize=MMG.zoom+'px 100%';
  lanes.style.setProperty('--lh', MMG.laneH+'px');
  lanes.style.setProperty('--ch', Math.max(12, MMG.laneH-10)+'px');
  lanes.classList.toggle('tight', MMG.laneH<32);
  /* the track-number gutter in front of the waveforms: one row per lane, same
     order and height, so "Track N" always lines up with its card's lane */
  var tracks=document.getElementById('mmg-tracks');
  tracks.style.setProperty('--lh', MMG.laneH+'px');
  tracks.innerHTML = '<div class="mmg-tk-sp"></div>' + (n ? MMG.items.map(function(i,idx){
    var lbl=i.label?esc(i.label):'Track '+(idx+1);
    var sw=i.color?'<span class="sw" style="background:'+esc(i.color)+'"></span>':'';
    /* 2026-09-01: green = this track is in the mix, red = it is left out.
       mmgRender() already filters muted layers before it posts to ffmpeg, so
       the ball is a true on/off for what you hear, not just a dimmed row. */
    var ball=mmgBall(!i.muted, esc(i.uid), esc(i.n));
    return '<div class="mmg-tk'+(MMG.selIds.indexOf(i.uid)>=0?' sel':'')+(i.muted?' muted':'')+'" data-uid="'+esc(i.uid)+'"'
      + ' title="'+lbl+(i.muted?' (off)':'')+' — right-click for options">'+sw+lbl+ball+'</div>';
  }).join('') : '');
  lanes.innerHTML = n ? MMG.items.map(function(i){
    var w=Math.max(6,(i.dur||0)*MMG.zoom), tw=!!(i.slots&&i.slots.length), narrow=w<64;
    return '<div class="mmg-lane'+(i.muted?' muted':'')+(i.hideName?' noname':'')+'" data-uid="'+esc(i.uid)+'"><span class="ln"><b>'+esc(i.n)+'</b><i>'+mmgFmt(i.start)+'</i></span>'
      + '<div class="mmg-card'+(MMG.selIds.indexOf(i.uid)>=0?' sel':'')+(tw?' tw':'')+(narrow?' narrow':'')+'" data-uid="'+esc(i.uid)+'"'
      + ' style="left:'+(i.start*MMG.zoom).toFixed(2)+'px;width:'+w.toFixed(2)+'px"'
      + ' title="'+esc(i.n)+'\n'+mmgFmt(i.start)+' → '+mmgFmt(i.start+(i.dur||0))+(tw?'\n(tweaked)':'')+(i.muted?'\n(muted)':'')+'\ndrag to move · right-click for options">'
      + '<div class="in"><canvas></canvas><span class="nm">'+esc(i.n)+'</span><span class="ts">'+mmgFmt(i.start)+'</span></div>'
      + '<span class="x" data-x="'+esc(i.uid)+'" title="Remove this track">&times;</span></div></div>';
  }).join('') : '<div class="mmg-empty"><b>No tracks yet.</b><br>'
      + 'Click an instrument in the library on the left and it plays; click it again '
      + 'with <b>Add sound</b> (or click any effect in the right rail) and it lands '
      + 'here as a track.<br>'
      + 'Every track is a lane on this ruler — drag its card to move it, '
      + '&larr;/&rarr; nudge by 1 ms, right-click a track name to rename or colour it.</div>';
  Array.prototype.forEach.call(lanes.querySelectorAll('.mmg-card'), function(card){
    var it=mmgItem(card.getAttribute('data-uid')); if(it) mmgWave(card,it);
  });
  mmgLaneLabels();
  mmgHeadDraw();
  if(MMG.ts) mmgTsFill();
  if(window.mstRenderSoon) mstRenderSoon();   // the effect rail mirrors this board
}
/* the track gutter's on/off dot — the same control as Voice Studio's m1Ball().
   The SFX merger has no placeholder rows, so there is only the per-clip form
   (m1Ball()'s data-rowball variant has nothing to address here). */
function mmgBall(on, uid, what){
  return '<span class="ball'+(on?' on':' off')+'" data-ball="'+uid+'" role="button"'
    + ' title="'+(on?'On — '+what+' plays in the merge. Click to take it out.'
                   :'Off — '+what+' is left out of the merge. Click to bring it back.')+'"></span>';
}
/* the sticky lane label only stands in for a card whose START has scrolled off
   the left edge; while the card's own name is on screen it would just double it */
function mmgLaneLabels(){
  var board=document.getElementById('mmg-board'), x0=board.scrollLeft;
  Array.prototype.forEach.call(document.querySelectorAll('#mmg-lanes .mmg-lane'), function(lane){
    var c=lane.querySelector('.mmg-card'), ln=lane.querySelector('.ln'); if(!c||!ln) return;
    ln.style.visibility = (parseFloat(c.style.left)||0) < x0-2 ? 'visible' : 'hidden';
  });
}
document.getElementById('mmg-board').addEventListener('scroll', function(){
  document.getElementById('mmg-tracks').scrollTop = this.scrollTop;   // vertical only — the gutter never scrolls sideways
  if(MMG.lblRaf) return; MMG.lblRaf=requestAnimationFrame(function(){ MMG.lblRaf=0; mmgLaneLabels(); mmgWavesRedraw(); });
});
/* ── waveform ───────────────────────────────────────────────────────────────
   Peak-envelope drawing, the way a DAW does it: one min/max column per DEVICE
   pixel, the RMS body filled inside the envelope, a zero line through the
   middle. The old drawing was a 40-peak-per-second envelope stretched over the
   card, so at any real zoom one peak covered 15+ px and the wave read as a row
   of blocks. Two things fix that: peaks are stored at ~8-sample resolution, and
   the canvas is cut to the VISIBLE slice of the card so its pixels are timeline
   pixels rather than a stretched thumbnail. */
var MMG_PK_CAP=150000;                 /* ≤ 1.8 MB of peaks per stem */
var MMG_SC={n:0,t:null,b:null,r:null}; /* column scratch, grown once, reused every frame */
function mmgScratch(n){ if(MMG_SC.n<n){ MMG_SC.t=new Float32Array(n); MMG_SC.b=new Float32Array(n); MMG_SC.r=new Float32Array(n); MMG_SC.n=n; } return MMG_SC; }
function mmgPeaks(ab){
  var n=ab.length, c0=ab.getChannelData(0), c1=ab.numberOfChannels>1?ab.getChannelData(1):null;
  /* floor of 8 samples/bucket: max zoom is 4800 px/s, so at 48 kHz a column is
     10 samples — finer buckets than that would be stored for nothing. */
  var B=8; while(Math.ceil(n/B)>MMG_PK_CAP) B*=2;
  var N=Math.max(1,Math.ceil(n/B));
  var mn=new Float32Array(N), mx=new Float32Array(N), rms=new Float32Array(N), pk=0;
  for(var i=0;i<N;i++){
    var a=i*B, e=Math.min(n,a+B), lo=0, hi=0, sq=0;
    for(var j=a;j<e;j++){
      var v=c1?(c0[j]+c1[j])*0.5:c0[j];
      if(v<lo) lo=v; if(v>hi) hi=v; sq+=v*v;
    }
    mn[i]=lo; mx[i]=hi; rms[i]=Math.sqrt(sq/Math.max(1,e-a));
    if(hi>pk) pk=hi; if(-lo>pk) pk=-lo;
  }
  return {mn:mn, mx:mx, rms:rms, B:B, n:n, N:N, pk:pk, dur:ab.duration};
}
/* One LINEAR scale for the whole board. The merger renders its stems at
   mix-safe levels (measured: −11 to −25 dBFS peak, −24 to −40 dBFS RMS), so
   drawing them against full scale is a hairline; normalising per STEM — what
   the old code did — is worse still, because then every layer looks equally
   loud and the gain knob does nothing to the picture. The loudest layer on the
   board sets the scale instead: shapes stay linear, layers stay comparable. */
function mmgWaveGain(){
  if(MMG.wGain!=null) return MMG.wGain;
  var mx=0;
  MMG.items.forEach(function(i){ var p=mmgWavePk(i); if(p && p.pk>mx) mx=p.pk; });
  MMG.wGain = mx>0 ? Math.min(12, 0.98/mx) : 1;
  return MMG.wGain;
}
/* display compression. Board gain alone leaves the quiet layers as hairlines
   (measured: the loudest stem on a real board peaks 4.6x the quietest), and a
   dB scale — tried at floors of −60 and −40 — flattens the contrast away and
   lifts the noise floor into visible fuzz. sqrt sits between them: every layer
   shows its shape, the louder layer is still visibly the louder one. */
function mmgWaveY(v, g){
  var a=Math.min(1, Math.abs(v)*g); if(a<=0) return 0;
  a=Math.sqrt(a); return v<0?-a:a;
}
function mmgWavePk(it){
  var pk=MMG.waves[it.stem]; if(pk && pk!==true) return pk;
  var w=MMG.waveByUid[it.uid]; return (w && w.pk) ? w.pk : null;   // knob sweep: last good peaks
}
/* the card is drawn in lane coordinates; only the part of it inside the board's
   scroll window (plus a small margin so a scroll of a few px is already drawn)
   gets a canvas. */
function mmgWaveDraw(card, it){
  var cv=card.querySelector('canvas'), inEl=card.querySelector('.in'); if(!cv||!inEl) return;
  var pk=mmgWavePk(it); if(!pk){ cv.style.display='none'; return; }
  var board=document.getElementById('mmg-board'); if(!board) return;
  var W=inEl.clientWidth, H=inEl.clientHeight;
  if(!(W>0&&H>0)){ cv.style.display='none'; return; }
  var cardL=(parseFloat(card.style.left)||0)+card.clientLeft, PAD=200;   // style.left is the border box; .in starts inside it
  var x0=Math.max(0, Math.floor(board.scrollLeft-PAD-cardL));
  var x1=Math.min(W, Math.ceil(board.scrollLeft+board.clientWidth+PAD-cardL));
  if(!(x1-x0>=1)){ cv.style.display='none'; return; }
  var dpr=Math.min(2, window.devicePixelRatio||1);
  var cw=Math.max(1,Math.round((x1-x0)*dpr)), chh=Math.max(2,Math.round(H*dpr));
  cv.style.display='block'; cv.style.left=x0+'px'; cv.style.width=(x1-x0)+'px';
  if(cv.width!==cw) cv.width=cw; if(cv.height!==chh) cv.height=chh;
  var ctx=cv.getContext('2d'); ctx.clearRect(0,0,cw,chh);
  var mid=chh/2, amp=mid-dpr, N=pk.N, B=pk.B, n=pk.n, g=mmgWaveGain();
  var sc=mmgScratch(cw), top=sc.t, bot=sc.b, rmsA=sc.r;
  for(var x=0;x<cw;x++){
    var s0=(x0+x/dpr)/W*n, s1=(x0+(x+1)/dpr)/W*n;
    var b0=Math.max(0,Math.min(N-1,Math.floor(s0/B))), b1=Math.max(b0+1,Math.min(N,Math.ceil(s1/B)));
    var lo=0, hi=0, r=0, c=0;
    for(var b=b0;b<b1;b++){ if(pk.mn[b]<lo) lo=pk.mn[b]; if(pk.mx[b]>hi) hi=pk.mx[b]; r+=pk.rms[b]; c++; }
    top[x]=mmgWaveY(hi,g); bot[x]=mmgWaveY(lo,g); rmsA[x]=c?Math.abs(mmgWaveY(r/c,g)):0;
  }
  var tw=card.classList.contains('tw');
  /* zero line first, so the envelope sits on top of it */
  ctx.fillStyle = tw?'rgba(255,224,168,.22)':'rgba(206,228,255,.22)';
  ctx.fillRect(0, Math.round(mid-dpr/2), cw, Math.max(1,Math.round(dpr)));
  ctx.fillStyle = tw?'rgba(255,214,138,.62)':'rgba(178,214,255,.62)';   // peak envelope
  for(var x2=0;x2<cw;x2++){
    var yt=mid-top[x2]*amp, yb=mid-bot[x2]*amp;
    ctx.fillRect(x2, yt, 1, Math.max(dpr, yb-yt));
  }
  ctx.fillStyle = tw?'rgba(255,240,214,.95)':'rgba(233,243,255,.95)';   // RMS body
  for(var x3=0;x3<cw;x3++){
    /* clamped to the envelope: zoomed in far enough a column sits entirely on
       one side of zero, and a symmetric RMS bar would spill past the peak */
    var rh=rmsA[x3]*amp; if(rh<=0) continue;
    var rt=Math.min(rh, top[x3]*amp), rb=Math.min(rh, -bot[x3]*amp);
    if(rt+rb<=0) continue;
    ctx.fillRect(x3, mid-rt, 1, Math.max(dpr, rt+rb));
  }
}
/* the visible window moved (scroll, resize): re-cut every card's slice */
function mmgWavesRedraw(){
  Array.prototype.forEach.call(document.querySelectorAll('#mmg-lanes .mmg-card'), function(c){
    var it=mmgItem(c.getAttribute('data-uid')); if(it) mmgWaveDraw(c,it);
  });
}
/* decode the stem once per (file, knobs); every card on that stem then draws */
function mmgWave(card, it){
  if(!it.url || !window.AudioContext && !window.webkitAudioContext) return;
  var key=it.stem, cv=card.querySelector('canvas'); if(!cv) return;
  var pk=MMG.waves[key];
  if(pk && pk!==true){ MMG.waveByUid[it.uid]={pk:pk}; mmgWaveDraw(card,it); return; }
  if(MMG.tw===it.uid && MMG.waveByUid[it.uid] && pk===undefined){
    /* a knob sweep would otherwise download + decode a fresh float32 stem per
       twist just for a 36 px strip; the dialog closing redraws it properly */
    MMG.waveByUid[it.uid].dirty=true; mmgWaveDraw(card,it); return;
  }
  if(pk===true){ mmgWaveDraw(card,it); return; }   // already decoding
  MMG.waves[key]=true;
  fetch(it.url,{cache:'no-store'}).then(function(r){ if(!r.ok) throw new Error(r.status); return r.arrayBuffer(); }).then(function(buf){
    MMG.actx=MMG.actx||new (window.AudioContext||window.webkitAudioContext)();
    return MMG.actx.decodeAudioData(buf);
  }).then(function(ab){
    MMG.waves[key]=mmgPeaks(ab); MMG.wGain=null;      // a louder layer rescales the board
    Array.prototype.forEach.call(document.querySelectorAll('#mmg-lanes .mmg-card'), function(c){
      var i2=mmgItem(c.getAttribute('data-uid')); if(i2) mmgWave(c,i2); });
  }).catch(function(){ delete MMG.waves[key]; });
}
/* dir = ±1 step through MMG_ZOOMS. ax is a CLIENT x to pin — the mouse for
   ctrl+wheel, the board's middle for the buttons and the keyboard. Without it
   the thing you were zooming in on slid away under the pointer. */
function mmgZoom(dir, ax){
  var board=document.getElementById('mmg-board');
  var px = (ax==null) ? board.clientWidth/2 : (ax - board.getBoundingClientRect().left);
  px = Math.max(0, Math.min(board.clientWidth, px));
  var t = (board.scrollLeft + px) / MMG.zoom;
  var i=0, best=1e9; MMG_ZOOMS.forEach(function(z,k){ var d=Math.abs(z-MMG.zoom); if(d<best){best=d;i=k;} });
  i=Math.max(0,Math.min(MMG_ZOOMS.length-1,i+dir));
  if(MMG_ZOOMS[i]===MMG.zoom) return;
  MMG.zoom=MMG_ZOOMS[i];
  mmgRenderBoard(); board.scrollLeft=Math.max(0, t*MMG.zoom - px); mmgPersist();
}
/* the layer axis. 26 px is the floor at which a card still holds its name. */
function mmgLaneClamp(h){ return Math.max(26, Math.min(64, Math.round(h))); }
function mmgLaneZoom(d){
  var h=mmgLaneClamp(MMG.laneH+d); if(h===MMG.laneH) return;
  MMG.laneH=h; mmgRenderBoard(); mmgPersist();
}
/* "fit the whole merge" means the whole merge: the tail AND the layers below the
   fold. Solving on mmgTotal() alone overshot — mmgRenderBoard draws
   span = max(total*1.08+0.5, 3) at width span*zoom+60, so the tail fell off. */
function mmgZoomFit(){
  var board=document.getElementById('mmg-board'), t=Math.max(mmgTotal(),0.5);
  var span=Math.max(t*1.08+0.5, 3);
  MMG.zoom=Math.max(16, Math.min(4800, (board.clientWidth-62)/span));
  var n=MMG.items.length, avail=board.clientHeight-36;     // minus the sticky ruler
  if(n>0 && avail>0) MMG.laneH=mmgLaneClamp(Math.min(46, avail/n));
  mmgRenderBoard(); board.scrollLeft=0; board.scrollTop=0; mmgPersist();
}

/* ── the selection (2026-08-25: it is a SET) ──
   MMG.selIds is everything selected; MMG.sel is the last one touched and stays
   what the single-card dialogs (Tweak, Set timestamp) act on. Painting never
   rebuilds the lanes: a rebuild inside a contextmenu handler emits a scroll
   event that closes the menu it just opened. */
function mmgSelect(uid, add){
  if(!uid){ MMG.selIds=[]; MMG.sel=null; }
  else if(add){
    var k=MMG.selIds.indexOf(uid);
    if(k>=0){ MMG.selIds.splice(k,1); MMG.sel=MMG.selIds.length?MMG.selIds[MMG.selIds.length-1]:null; }
    else { MMG.selIds.push(uid); MMG.sel=uid; }
  } else { MMG.selIds=[uid]; MMG.sel=uid; }
  mmgPaintSel();
  if(window.mstRender) mstRender();   // the effect rail shows THIS layer's chain
}
function mmgSelectSet(ids){
  MMG.selIds=ids.slice(); MMG.sel=ids.length?ids[ids.length-1]:null; mmgPaintSel();
}
function mmgPaintSel(){
  Array.prototype.forEach.call(document.querySelectorAll('.mmg-card.sel,.mmg-tk.sel'),function(el){ el.classList.remove('sel'); });
  MMG.selIds.forEach(function(u){
    var c=document.querySelector('#mmg-lanes .mmg-card[data-uid="'+u+'"]'); if(c) c.classList.add('sel');
    var tk=document.querySelector('#mmg-tracks .mmg-tk[data-uid="'+u+'"]'); if(tk) tk.classList.add('sel');
  });
  mmgSelInfo();
}
function mmgSelInfo(){
  var el=document.getElementById('mmg-selinfo'); if(!el) return;
  el.textContent = MMG.selIds.length>1 ? MMG.selIds.length+' selected' : '';
}

/* ── mouse on the board: select, drag cards (ms-snapped), ruler seek/hover ── */
(function(){
  var lanes=document.getElementById('mmg-lanes'), ruler=document.getElementById('mmg-ruler'),
      board=document.getElementById('mmg-board'), canvas=document.getElementById('mmg-canvas'), DRG=null, MRQ=null;
  function hover(x, t){ var hv=document.getElementById('mmg-hv'), hl=document.getElementById('mmg-hvl');
    if(x==null){ hv.style.display='none'; hl.style.display='none'; return; }
    hv.style.display='block'; hl.style.display='block'; hv.style.left=x+'px'; hl.style.left=x+'px'; hl.textContent=mmgFmtMs(t); }
  function relX(e){ return e.clientX-canvas.getBoundingClientRect().left; }
  lanes.addEventListener('click', function(e){
    var x=e.target.closest?e.target.closest('.mmg-card .x'):null;
    if(x){ e.stopPropagation(); mmgRemove(x.getAttribute('data-x')); return; }
  });
  /* ── rubber band (2026-08-25) ──
     Hold the left button on empty lane space and drag a box over the cards.
     ctrl / shift keeps whatever was already selected. The box is clamped to the
     visible board so it never paints over the header or the list below, and it
     hit-tests with getBoundingClientRect so scroll, zoom and lane height are
     all somebody else's problem. */
  function marqRect(e){
    var br=board.getBoundingClientRect();
    function cx(v){ return Math.max(br.left, Math.min(br.right, v)); }
    function cy(v){ return Math.max(br.top, Math.min(br.bottom, v)); }
    var x0=cx(MRQ.x0), y0=cy(MRQ.y0), x1=cx(e.clientX), y1=cy(e.clientY);
    return {left:Math.min(x0,x1), top:Math.min(y0,y1), right:Math.max(x0,x1), bottom:Math.max(y0,y1)};
  }
  function marqPaint(r){
    var m=document.getElementById('mmg-marq');
    m.style.display='block'; m.style.left=r.left+'px'; m.style.top=r.top+'px';
    m.style.width=Math.max(0,r.right-r.left)+'px'; m.style.height=Math.max(0,r.bottom-r.top)+'px';
  }
  function marqHit(r){
    var ids=MRQ.base.slice();
    Array.prototype.forEach.call(lanes.querySelectorAll('.mmg-card'), function(c){
      var b=c.getBoundingClientRect();
      if(b.right<r.left || b.left>r.right || b.bottom<r.top || b.top>r.bottom) return;
      var u=c.getAttribute('data-uid'); if(ids.indexOf(u)<0) ids.push(u);
    });
    return ids;
  }
  lanes.addEventListener('pointerdown', function(e){
    if(e.button!==0) return;
    if(e.target.closest && e.target.closest('.mmg-card .x')) return;
    var card=e.target.closest?e.target.closest('.mmg-card'):null;
    if(!card){
      /* empty lane space: start the band. A press with no drag clears. */
      e.preventDefault();
      MRQ={x0:e.clientX, y0:e.clientY, pid:e.pointerId, moved:false,
           base:(e.ctrlKey||e.metaKey||e.shiftKey)?MMG.selIds.slice():[]};
      try{ lanes.setPointerCapture(e.pointerId); }catch(err){}
      return;
    }
    var it=mmgItem(card.getAttribute('data-uid')); if(!it) return;
    e.preventDefault();
    /* ctrl toggles a card in or out; shift stays the fine-drag modifier */
    if(e.ctrlKey||e.metaKey) mmgSelect(it.uid, true);
    else if(MMG.selIds.indexOf(it.uid)<0) mmgSelect(it.uid);
    else MMG.sel=it.uid;
    /* a card inside a multi-selection drags the WHOLE selection with it */
    var grp=(MMG.selIds.length>1 && MMG.selIds.indexOf(it.uid)>=0)
      ? MMG.selIds.map(function(u){ return mmgItem(u); }).filter(Boolean) : [it];
    DRG={it:it, card:card, x0:e.clientX, s0:it.start, moved:false, pid:e.pointerId,
         grp:grp.map(function(o){ return {it:o, s0:o.start}; })};
    try{ card.setPointerCapture(e.pointerId); }catch(err){}
  });
  lanes.addEventListener('pointermove', function(e){
    if(MRQ){
      if(!MRQ.moved && Math.abs(e.clientX-MRQ.x0)<3 && Math.abs(e.clientY-MRQ.y0)<3) return;
      MRQ.moved=true;
      var r=marqRect(e); marqPaint(r); mmgSelectSet(marqHit(r));
      return;
    }
    if(!DRG) return;
    var dx=e.clientX-DRG.x0; if(!DRG.moved && Math.abs(dx)<2) return;
    DRG.moved=true; MMG.dragging=true; DRG.card.classList.add('drag');
    var s=DRG.s0+(dx/MMG.zoom)*(e.shiftKey?0.1:1);
    var grid=e.ctrlKey?0.01:0.001; s=Math.max(0, Math.round(s/grid)*grid);
    /* the group travels as one and hits 0 as one — clamping each card on its own
       would pile the whole selection up on the left wall and lose its spacing */
    var d=s-DRG.s0, floor=Infinity;
    DRG.grp.forEach(function(g){ floor=Math.min(floor,g.s0); });
    if(floor+d<0) d=-floor;
    DRG.grp.forEach(function(g){
      g.it.start=+Math.max(0,g.s0+d).toFixed(3);
      var c=lanes.querySelector('.mmg-card[data-uid="'+g.it.uid+'"]'); if(!c) return;
      c.style.left=(g.it.start*MMG.zoom).toFixed(2)+'px';
      var ts=c.querySelector('.ts'); if(ts) ts.textContent=mmgFmt(g.it.start);
      var ln=c.parentElement.querySelector('.ln i'); if(ln) ln.textContent=mmgFmt(g.it.start);
    });
    mmgLaneLabels();
    hover(DRG.it.start*MMG.zoom, DRG.it.start);
  });
  function up(e){
    if(MRQ){
      var m=MRQ; MRQ=null;
      document.getElementById('mmg-marq').style.display='none';
      try{ lanes.releasePointerCapture(m.pid); }catch(err){}
      if(!m.moved && !m.base.length) mmgSelect(null);   // a click on empty space deselects
      return;
    }
    if(!DRG) return;
    var d=DRG; DRG=null; d.card.classList.remove('drag'); hover(null);
    MMG.dragging=false;
    try{ d.card.releasePointerCapture(d.pid); }catch(err){}
    if(!d.moved){ if(MMG.rebuild){ MMG.rebuild=false; mmgRenderBoard(); } return; }
    MMG.rebuild=false; MMG.mixDirty=true; mmgRenderBoard(); mmgPersist();
    /* the moved cards play at their new time: from just before the FIRST lands */
    var from=Infinity; d.grp.forEach(function(g){ from=Math.min(from,g.it.start); });
    mmgRender({why:'move', play:true, from:Math.max(0, from-0.25)});
  }
  lanes.addEventListener('pointerup', up); lanes.addEventListener('pointercancel', up);
  /* the captured card can be detached by a rebuild that was already queued; the
     document still sees the release */
  document.addEventListener('pointerup', up); document.addEventListener('pointercancel', up);
  ruler.addEventListener('mousemove', function(e){ if(DRG) return; var x=relX(e); hover(x, x/MMG.zoom); });
  ruler.addEventListener('mouseleave', function(){ if(!DRG) hover(null); });
  ruler.addEventListener('click', function(e){
    var t=relX(e)/MMG.zoom, a=mmgAudio();
    if(MMG.mix && MMG.mix.url && !MMG.stemPlaying && a.getAttribute('data-src')===MMG.mix.url && !isNaN(a.duration)){
      try{ a.currentTime=Math.min(t, a.duration-0.01); }catch(err){} mmgHeadDraw();
    } else if(MMG.items.length){ if(!MMG.mix||MMG.mixDirty) mmgRender({why:'seek', play:true, from:t}); else mmgPlay(t); }
  });
  board.addEventListener('wheel', function(e){
    if(!e.ctrlKey) return;
    e.preventDefault();
    /* ctrl+shift = the layer axis, so a 13-layer merge can be squeezed onto one screen */
    if(e.shiftKey) mmgLaneZoom(e.deltaY<0?4:-4); else mmgZoom(e.deltaY<0?1:-1, e.clientX);
  }, {passive:false});
})();

/* ── keyboard (called from the SFX tab's key handler) ── */
function mmgKey(e){
  var menu=document.getElementById('mmg-menu');
  if(e.key==='Escape'){
    if(menu.style.display==='block'){ mmgMenuClose(); return true; }
    if(document.getElementById('mmg-tweak').classList.contains('on')){ mmgTwClose(); return true; }
    if(document.getElementById('mmg-ts').classList.contains('on')){ mmgTsClose(); return true; }
    if(document.getElementById('mmg-tked').classList.contains('on')){ mmgTkEditClose(); return true; }
    if(document.getElementById('mmg-mixer').classList.contains('on')){ mmgMixerClose(); return true; }
    if(MMG.playing){ mmgStop(); return true; }
    if(MMG.shown && MMG.sel){ mmgSelect(null); return true; }
    return false;
  }
  /* + / − zoom the timeline, 0 fits. ctrl+ / ctrl− stay the browser's page zoom. */
  if(MMG.shown && !e.ctrlKey && !e.metaKey && !e.altKey &&
     (e.key==='+'||e.key==='='||e.key==='-'||e.key==='_'||e.key==='0')){
    e.preventDefault();
    if(e.key==='0') mmgZoomFit();
    else if(e.shiftKey) mmgLaneZoom((e.key==='-'||e.key==='_')?-4:4);
    else mmgZoom((e.key==='-'||e.key==='_')?-1:1);
    return true;
  }
  if(MMG.shown && MMG.items.length && (e.key==='a'||e.key==='A') && (e.ctrlKey||e.metaKey)){
    e.preventDefault(); mmgSelectSet(MMG.items.map(function(i){ return i.uid; })); return true;
  }
  if(!MMG.shown || !MMG.sel) return false;
  var it=mmgItem(MMG.sel); if(!it) return false;
  /* every key below acts on the whole selection, not just the last card touched */
  var grp=MMG.selIds.map(function(u){ return mmgItem(u); }).filter(Boolean);
  if(!grp.length) grp=[it];
  if(e.key==='ArrowLeft' || e.key==='ArrowRight'){
    e.preventDefault();
    var d=(e.ctrlKey?0.1:(e.shiftKey?0.01:0.001))*(e.key==='ArrowLeft'?-1:1), floor=Infinity;
    grp.forEach(function(g){ floor=Math.min(floor,g.start); });
    if(floor+d<0) d=-floor;                       // the group stops at 0 together
    grp.forEach(function(g){ g.start=+Math.max(0,g.start+d).toFixed(3); });
    MMG.mixDirty=true; mmgRenderBoard(); mmgPersist();
    clearTimeout(MMG.nudgeT);
    MMG.nudgeT=setTimeout(function(){ var f=Infinity; grp.forEach(function(g){ f=Math.min(f,g.start); });
      mmgRender({why:'move', play:true, from:Math.max(0,f-0.25)}); }, 380);
    return true;
  }
  if(e.key==='Delete' || e.key==='Backspace'){
    e.preventDefault();
    if(grp.length>1) mmgRemoveMany(grp.map(function(g){ return g.uid; })); else mmgRemove(it.uid);
    return true;
  }
  if(e.key===' '){
    /* a sample loaded in the player keeps its space bar unless the merge is what is playing */
    if(!MMG.playing && MUS.curRec) return false;
    e.preventDefault(); mmgTogglePlay(); return true;
  }
  return false;
}

/* ── right-click menus ── */
function mmgMenu(e, entries){
  var m=document.getElementById('mmg-menu'); MMG.menuFns=[];
  m.innerHTML=entries.map(function(en){
    if(en.sep) return '<hr>';
    var k=MMG.menuFns.push(en.fn)-1;
    return '<div data-k="'+k+'" class="'+(en.off?'off ':'')+(en.danger?'danger':'')+'">'+en.label+(en.note?'<small>'+esc(en.note)+'</small>':'')+'</div>';
  }).join('');
  m.style.display='block'; MMG.menuAt=Date.now();
  m.style.left=Math.min(e.clientX, window.innerWidth-220)+'px';
  m.style.top=Math.min(e.clientY, window.innerHeight-(entries.length*34+16))+'px';
}
function mmgMenuClose(){ document.getElementById('mmg-menu').style.display='none'; }
(function(){
  var m=document.getElementById('mmg-menu');
  m.addEventListener('click', function(e){
    var d=e.target.closest?e.target.closest('div[data-k]'):null; if(!d) return;
    if(d.classList.contains('off')) return;
    var fn=MMG.menuFns[+d.getAttribute('data-k')]; mmgMenuClose(); if(fn) fn();
  });
  document.addEventListener('click', function(e){ if(!m.contains(e.target)) mmgMenuClose(); });
  document.addEventListener('contextmenu', function(e){ if(!m.contains(e.target)) mmgMenuClose(); }, true);
  window.addEventListener('scroll', function(e){ if(!m.contains(e.target) && Date.now()-(MMG.menuAt||0)>250) mmgMenuClose(); }, true);
  window.addEventListener('blur', mmgMenuClose);
})();
document.getElementById('mus-rail').addEventListener('contextmenu', function(e){
  var row=e.target.closest?e.target.closest('.mus-file'):null; if(!row) return;
  var r=MUS.shown[+row.getAttribute('data-i')]; if(!r) return;
  e.preventDefault();
  var inList=mmgFind(r.c,r.f).length;
  var entries=[
    {label:'&#10133;&nbsp; Add as a track', fn:function(){ mmgAdd(r); }},
    {label:'&#10134;&nbsp; Remove its tracks', off:!inList, note:inList>1?('×'+inList):'', fn:function(){ mmgRemoveFile(r.c,r.f); }},
    {label:'&#127899;&nbsp; Tweak sound', fn:function(){ mmgTweakRec(r); }},
  ];
  if(r.c==='merged') entries.push({sep:true}, {label:'&#9881;&nbsp; Open in the mixer', note:'recipe', fn:function(){ mmgOpenRecipe(r); }});
  mmgMenu(e, entries);
});
/* right-clicking a card that is part of a rubber-band selection keeps that
   selection and offers the group remove; right-clicking outside it selects the
   one card first, so the menu can never act on something off screen */
function mmgCardMenu(e, it){
  if(MMG.selIds.indexOf(it.uid)<0) mmgSelect(it.uid); else MMG.sel=it.uid;
  var n=MMG.selIds.length, entries=[];
  if(n>1){
    var ids=MMG.selIds.slice();
    entries.push({label:'&#10060;&nbsp; Remove '+n+' selected tracks', danger:true, fn:function(){ mmgRemoveMany(ids); }});
  }
  entries.push(
    {label:'&#10060;&nbsp; Remove track', danger:true, note:(n>1?it.n:''), fn:function(){ mmgRemove(it.uid); }},
    {label:'&#9201;&nbsp; Set timestamp', note:mmgFmt(it.start), fn:function(){ mmgTsOpen(it.uid); }},
    {label:'&#127899;&nbsp; Tweak sound', fn:function(){ mmgTweakOpen(it.uid); }},
    {label:'&#128065;&nbsp; '+(it.hideName?'Show Source Name':'Hide Source Name'), fn:function(){ mmgToggleHideName(it.uid); }});
  mmgMenu(e, entries);
}
function mmgToggleHideName(uid){
  var it=mmgItem(uid); if(!it) return;
  it.hideName=!it.hideName; mmgRenderBoard(); mmgPersist();
}
document.getElementById('mmg-lanes').addEventListener('contextmenu', function(e){
  var card=e.target.closest?e.target.closest('.mmg-card'):null;
  if(card){
    var it=mmgItem(card.getAttribute('data-uid')); if(!it) return;
    e.preventDefault(); mmgCardMenu(e, it); return;
  }
  /* right-clicking the lane itself (not its clip) highlights the track and
     opens its FL-style mixer — right-clicking the clip keeps the menu above */
  var lane=e.target.closest?e.target.closest('.mmg-lane'):null; if(!lane) return;
  var it2=mmgItem(lane.getAttribute('data-uid')); if(!it2) return;
  e.preventDefault(); mmgSelect(it2.uid); mmgMixerOpen(it2.uid);
});
/* ── the track gutter ("Track 1", "Track 2", …) ──
   click selects (highlights the matching card's edge, same .sel class);
   right-click opens the FL Studio track menu, unusable items grayed out. */
document.getElementById('mmg-tracks').addEventListener('click', function(e){
  var ball=e.target.closest?e.target.closest('.ball'):null;
  if(ball){                                     /* on/off, not a selection */
    e.stopPropagation();
    var it=mmgItem(ball.getAttribute('data-ball')); if(!it) return;
    mmgTrackMute(it.uid, !it.muted); return;
  }
  var tk=e.target.closest?e.target.closest('.mmg-tk'):null; if(!tk) return;
  mmgSelect(tk.getAttribute('data-uid'));
});
document.getElementById('mmg-tracks').addEventListener('contextmenu', function(e){
  var tk=e.target.closest?e.target.closest('.mmg-tk'):null; if(!tk) return;
  var it=mmgItem(tk.getAttribute('data-uid')); if(!it) return;
  e.preventDefault(); mmgSelect(it.uid); mmgTrackMenu(e, it);
});
/* every item that isn't a real action here (no clip grouping, no plugin
   icons, no automation track types) is off:true — greyed, not clickable —
   rather than dropped, so the menu still reads as the FL one, in FL's order */
function mmgTrackMenu(e, it){
  var idx=MMG.items.indexOf(it); if(idx<0) return;
  mmgMenu(e, [
    {label:'Rename, color and icon…', fn:function(){ mmgTkEditOpen(it.uid); }},
    {label:'Random color', fn:function(){ mmgTrackRandomColor(it.uid); }},
    {label:'Change color…', fn:function(){ mmgTkEditOpen(it.uid); }},
    {label:'Change icon…', off:true},
    {label:'Auto name', fn:function(){ mmgTrackAutoName(it.uid); }},
    {label:'Auto name clips', off:true},
    {label:'Reset', fn:function(){ mmgTrackReset(it.uid); }},
    {sep:true},
    {label:'Track mode', off:true, note:'▸'},
    {label:'Performance settings', off:true, note:'▸'},
    {sep:true},
    {label:'Size', off:true, note:'▸'},
    {label:'Lock to this size', off:true},
    {sep:true},
    {label:'Group with above track', off:true},
    {label:'Ungroup', off:true},
    {label:'Auto color group', off:true},
    {sep:true},
    {label:'Current clip source', off:true},
    {label:'Lock to content', off:true},
    {label:'Merge tracks', off:true},
    {label:'Consolidate track(s)', off:true, note:'▸'},
    {label:'Mute all clips', off:!!it.muted, fn:function(){ mmgTrackMute(it.uid,true); }},
    {label:'Unmute all clips', off:!it.muted, fn:function(){ mmgTrackMute(it.uid,false); }},
    {sep:true},
    {label:'Insert one', off:true},
    {label:'Clone…', fn:function(){ mmgTrackClone(it.uid); }},
    {label:'Delete', danger:true, fn:function(){ mmgRemove(it.uid); }},
    {sep:true},
    {label:'Move up', off:idx<=0, fn:function(){ mmgTrackMove(it.uid,-1); }},
    {label:'Move down', off:idx>=MMG.items.length-1, fn:function(){ mmgTrackMove(it.uid,1); }},
  ]);
}
function mmgTrackAutoName(uid){ var it=mmgItem(uid); if(!it) return; it.label=''; mmgRenderBoard(); mmgPersist(); }
function mmgTrackRandomColor(uid){
  var it=mmgItem(uid); if(!it) return;
  it.color='#'+('00000'+Math.floor(Math.random()*0xffffff).toString(16)).slice(-6);
  mmgRenderBoard(); mmgPersist();
}
function mmgTrackReset(uid){ var it=mmgItem(uid); if(!it) return; it.label=''; it.color=''; mmgRenderBoard(); mmgPersist(); }
function mmgTrackMute(uid, val){
  var it=mmgItem(uid); if(!it) return;
  it.muted=!!val; mmgRenderBoard(); mmgPersist(); mmgRender({why:'mute', play:false});
}
function mmgTrackClone(uid){
  var it=mmgItem(uid); if(!it) return;
  var idx=MMG.items.indexOf(it);
  MMG.items.splice(idx+1, 0, {uid:mmgUid(), c:it.c, f:it.f, n:it.n, d:it.d, start:it.start,
    slots:JSON.parse(JSON.stringify(it.slots||[])), dur:it.dur, stem:'', url:'',
    label:it.label, color:it.color, muted:it.muted});
  mmgRenderBoard(); mmgPersist(); mmgRender({why:'add', play:false});
}
function mmgTrackMove(uid, dir){
  var it=mmgItem(uid); if(!it) return;
  var idx=MMG.items.indexOf(it), j=idx+dir; if(j<0||j>=MMG.items.length) return;
  MMG.items[idx]=MMG.items[j]; MMG.items[j]=it;
  mmgRenderBoard(); mmgPersist();
}
/* ── Rename, color and icon ── */
function mmgTkEditOpen(uid){
  var it=mmgItem(uid); if(!it) return;
  MMG.tked=uid;
  document.getElementById('mmg-tked-title').textContent='Rename, color and icon — '+(it.label||('Track '+(MMG.items.indexOf(it)+1)));
  document.getElementById('mmg-tked-name').value=it.label||'';
  document.getElementById('mmg-tked-color').value=it.color||'#00e5ff';
  mmgDlgPlace('mmg-tked', window.innerWidth/2-165, window.innerHeight/2-150);
}
function mmgTkEditApply(){
  var it=mmgItem(MMG.tked); if(!it) return;
  it.label=document.getElementById('mmg-tked-name').value.trim();
  it.color=document.getElementById('mmg-tked-color').value||'';
  mmgTkEditClose(); mmgRenderBoard(); mmgPersist();
}
function mmgTkEditClearColor(){
  var it=mmgItem(MMG.tked); if(it){ it.color=''; mmgRenderBoard(); mmgPersist(); }
  document.getElementById('mmg-tked-color').value='#00e5ff';
}
function mmgTkEditClose(){ MMG.tked=null; document.getElementById('mmg-tked').classList.remove('on'); }
/* ── the FL-style Mixer panel (2026-08-30) ──
   Each row is one slot in it.slots — empty until something is added. Loaded
   slots open their knobs on click; right-click on ANY row (loaded or empty)
   is the FL "Select/Delete/Move up/Move down" menu, via the same mmgMenu()
   every other right-click list in this tab uses. */
function mmgEffectType(id){ return (MMG.spec.effect_types||[]).filter(function(e){ return e.id===id; })[0]||null; }
function mmgMixerOpen(uid){
  mmgSpec().then(function(){
    var it=mmgItem(uid); if(!it) return;
    MMG.mixer=uid;
    document.getElementById('mmg-mx-title').textContent='Mixer — '+(it.label||('Track '+(MMG.items.indexOf(it)+1)));
    mmgMixerDraw();
    mmgDlgPlace('mmg-mixer', window.innerWidth-380, 90);
  }).catch(function(e){ alert('Mixer unavailable: '+(e.message||e)); });
}
function mmgMixerDraw(){
  var it=mmgItem(MMG.mixer); if(!it||!MMG.spec) return;
  var slots=it.slots||[], max=MMG.spec.max_slots||10, rows=[];
  slots.forEach(function(s,idx){
    var et=mmgEffectType(s.type), title=et?et.title:s.type;
    rows.push('<div class="mmgmx-slot loaded" data-idx="'+idx+'" title="'+esc(title)+' — click to open its knobs, right-click for options">'
      + '<span class="tw">&#9656;</span><span class="lb">'+esc(title)+'</span><span class="dot"></span><span class="dot"></span></div>');
  });
  for(var i=slots.length;i<max;i++) rows.push('<div class="mmgmx-slot" data-idx="'+i+'" title="right-click to add an effect"><span class="tw">&#9656;</span><span class="lb">Slot '+(i+1)+'</span><span class="dot"></span><span class="dot"></span></div>');
  document.getElementById('mmg-mx-slots').innerHTML=rows.join('');
}
function mmgMixerClose(){
  if(MMG.recStream) mmgRecStop();            // a take must not keep the mic open past its dialog
  MMG.mixer=null; document.getElementById('mmg-mixer').classList.remove('on');
}
document.getElementById('mmg-mx-slots').addEventListener('click', function(e){
  var s=e.target.closest?e.target.closest('.mmgmx-slot.loaded'):null; if(!s||!MMG.mixer) return;
  mmgTweakOpen(MMG.mixer, +s.getAttribute('data-idx'));
});
document.getElementById('mmg-mx-slots').addEventListener('contextmenu', function(e){
  var row=e.target.closest?e.target.closest('.mmgmx-slot'):null; if(!row||!MMG.mixer) return;
  e.preventDefault();
  var it=mmgItem(MMG.mixer); if(!it) return;
  var idx=+row.getAttribute('data-idx'), slots=it.slots||[], max=(MMG.spec&&MMG.spec.max_slots)||10;
  if(idx<slots.length){
    mmgMenu(e, [
      {label:'&#127899;&nbsp; Tweak sound', fn:function(){ mmgTweakOpen(it.uid, idx); }},
      {sep:true},
      {label:'&#11014;&nbsp; Move up', off:idx<=0, fn:function(){ mmgSlotMove(it.uid, idx, -1); }},
      {label:'&#11015;&nbsp; Move down', off:idx>=slots.length-1, fn:function(){ mmgSlotMove(it.uid, idx, 1); }},
      {sep:true},
      {label:'&#10060;&nbsp; Remove', danger:true, fn:function(){ mmgSlotRemove(it.uid, idx); }},
    ]);
  } else {
    var types=(MMG.spec.effect_types&&MMG.spec.effect_types.length)?MMG.spec.effect_types:[{id:'tweak',title:'Tweaker'}];
    mmgMenu(e, types.map(function(et){
      return {label:esc(et.title), off:slots.length>=max,
              fn:function(){ mmgSlotAdd(it.uid, et.id); }};
    }));
  }
});
/* ── slot list edits: add/remove/reorder, then re-render the mix ── */
function mmgSlotsChanged(it){
  MMG.mixDirty=true; mmgPersist();
  var card=document.querySelector('#mmg-lanes .mmg-card[data-uid="'+it.uid+'"]'); if(card) card.classList.toggle('tw', !!(it.slots&&it.slots.length));
  mmgRender({why:'tweak', play:true, from:Math.max(0,it.start-0.25)});
}
function mmgSlotAdd(uid, typ){
  var it=mmgItem(uid); if(!it) return;
  typ=typ||'tweak';
  it.slots=it.slots||[];
  if(it.slots.length>=((MMG.spec&&MMG.spec.max_slots)||10)) return;
  it.slots.push({type:typ, tweak:mmgDefaults(typ)});
  if(MMG.mixer===uid) mmgMixerDraw();
  mmgSlotsChanged(it);
  mmgTweakOpen(uid, it.slots.length-1);
}
function mmgSlotRemove(uid, idx){
  var it=mmgItem(uid); if(!it||!it.slots||!it.slots[idx]) return;
  it.slots.splice(idx,1);
  if(MMG.tw===uid && MMG.twSlot===idx) mmgTwClose();
  else if(MMG.tw===uid && MMG.twSlot>idx) MMG.twSlot--;
  if(MMG.mixer===uid) mmgMixerDraw();
  mmgSlotsChanged(it);
}
function mmgSlotMove(uid, idx, dir){
  var it=mmgItem(uid); if(!it||!it.slots) return;
  var j=idx+dir; if(j<0||j>=it.slots.length) return;
  var tmp=it.slots[idx]; it.slots[idx]=it.slots[j]; it.slots[j]=tmp;
  if(MMG.tw===uid){ if(MMG.twSlot===idx) MMG.twSlot=j; else if(MMG.twSlot===j) MMG.twSlot=idx; }
  if(MMG.mixer===uid) mmgMixerDraw();
  mmgSlotsChanged(it);
}
/* ── the plug row: pick a real input device (Focusrite &c.) and record straight
   into a new layer. The Linux box behind this tab cannot see the operator's
   audio interface — only the BROWSER can, via its own device-permission API —
   so this is entirely client-side until the take is uploaded. ── */
function mmgRecDevices(){
  if(!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices)
    return Promise.reject(new Error('this browser exposes no microphone API'));
  return navigator.mediaDevices.enumerateDevices().then(function(list){
    var ins=list.filter(function(d){ return d.kind==='audioinput'; });
    if(ins.length && ins.every(function(d){ return !d.label; })){
      /* labels are blank until permission is granted at least once */
      return navigator.mediaDevices.getUserMedia({audio:true}).then(function(s){
        s.getTracks().forEach(function(t){ t.stop(); });
        return navigator.mediaDevices.enumerateDevices();
      }).then(function(list2){ return list2.filter(function(d){ return d.kind==='audioinput'; }); });
    }
    return ins;
  });
}
function mmgRecDeviceSet(id, label){
  MMG.recDevice=id; MMG.recDeviceLabel=label||'';
  var el=document.getElementById('mmg-mx-input'); if(el) el.textContent=id?(label||'Microphone'):'(none)';
}
function mmgRecDevicePick(e){
  mmgRecDevices().then(function(devs){
    var entries=devs.map(function(d){
      return {label:(d.deviceId===MMG.recDevice?'&#10003;&nbsp;':'&#127908;&nbsp;')+esc(d.label||'Microphone'),
              fn:function(){ mmgRecDeviceSet(d.deviceId, d.label); }};
    });
    if(!devs.length) entries.push({label:'no input devices found', off:true});
    entries.push({sep:true}, {label:'(none)', fn:function(){ mmgRecDeviceSet('',''); }});
    mmgMenu(e, entries);
  }).catch(function(err){ alert('Could not list input devices: '+(err.message||err)); });
}
function mmgRecUI(on){
  var b=document.getElementById('mmg-mx-recbtn'); if(!b) return;
  b.classList.toggle('on', on);
  b.innerHTML = on ? '&#9209;' : '&#9210;';
  b.title = on ? 'Stop recording' : 'Record from this input into a new layer';
}
function mmgRecToggle(){ if(MMG.recStream) mmgRecStop(); else mmgRecStart(); }
function mmgRecStart(){
  if(!MMG.recDevice){ alert('Pick an input device first — click "(none)" above the slot list.'); return; }
  if(!navigator.mediaDevices || !window.MediaRecorder){ alert('This browser cannot record audio.'); return; }
  navigator.mediaDevices.getUserMedia({audio:{deviceId:{exact:MMG.recDevice}}}).then(function(stream){
    MMG.recStream=stream; MMG.recChunks=[];
    var mimes=['audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus'];
    var mime=mimes.filter(function(m){ return window.MediaRecorder.isTypeSupported && MediaRecorder.isTypeSupported(m); })[0];
    var rec=MMG.recRecorder = mime ? new MediaRecorder(stream,{mimeType:mime}) : new MediaRecorder(stream);
    rec.ondataavailable=function(e){ if(e.data && e.data.size) MMG.recChunks.push(e.data); };
    rec.onstop=mmgRecUpload;
    rec.start();
    mmgRecUI(true); mmgStatus('recording from '+(MMG.recDeviceLabel||'input')+'…');
  }).catch(function(e){ alert('Could not open '+(MMG.recDeviceLabel||'that input')+': '+(e.message||e)); });
}
function mmgRecStop(){
  if(MMG.recRecorder && MMG.recRecorder.state!=='inactive') MMG.recRecorder.stop();
  if(MMG.recStream) MMG.recStream.getTracks().forEach(function(t){ t.stop(); });
  MMG.recStream=null; mmgRecUI(false);
}
function mmgRecUpload(){
  var blob=new Blob(MMG.recChunks, {type:(MMG.recRecorder&&MMG.recRecorder.mimeType)||'audio/webm'});
  MMG.recChunks=[]; MMG.recRecorder=null;
  if(!blob.size){ mmgStatus('recording was empty','var(--bad)'); return; }
  var name='Recording '+new Date().toISOString().slice(0,16).replace('T',' ');
  mmgStatus('uploading recording…');
  var xhr=new XMLHttpRequest();
  xhr.open('POST','/inspect/api/merge/record?name='+encodeURIComponent(name));
  xhr.onload=function(){
    var d=null; try{ d=JSON.parse(xhr.responseText); }catch(err){}
    if(!d || d.error){ mmgStatus('recording upload failed','var(--bad)'); alert('Could not save the recording: '+((d&&d.error)||xhr.status)); return; }
    mmgAdd({c:d.cat, f:d.file, n:d.name, d:d.duration});
    musLoad(true);
    mmgStatus('recorded '+mmgFmt(d.duration)+' · added as a new layer','var(--good)');
  };
  xhr.onerror=function(){ mmgStatus('recording upload failed','var(--bad)'); };
  xhr.send(blob);
}
document.getElementById('mmg-mixer').addEventListener('click', function(e){
  if(e.target.closest('#mmg-mx-input')) return mmgRecDevicePick(e);
  if(e.target.closest('#mmg-mx-recbtn')) return mmgRecToggle();
});

/* ── draggable dialogs (title bar = handle) ── */
(function(){
  var D=null;
  document.addEventListener('pointerdown', function(e){
    var hd=e.target.closest?e.target.closest('.mmg-dlg .hd'):null; if(!hd) return;
    if(e.target.closest('button,input,.vx-seg')) return;
    var box=document.getElementById(hd.getAttribute('data-drag')); if(!box) return;
    var r=box.getBoundingClientRect();
    D={box:box, dx:e.clientX-r.left, dy:e.clientY-r.top, pid:e.pointerId, hd:hd};
    try{ hd.setPointerCapture(e.pointerId); }catch(err){}
    e.preventDefault();
  });
  document.addEventListener('pointermove', function(e){
    if(!D) return;
    var w=D.box.offsetWidth, h=D.box.offsetHeight;
    var x=Math.max(0,Math.min(window.innerWidth-Math.min(w,120), e.clientX-D.dx));
    var y=Math.max(0,Math.min(window.innerHeight-40, e.clientY-D.dy));
    D.box.style.left=x+'px'; D.box.style.top=y+'px'; D.box.style.right='auto'; D.box.style.bottom='auto';
  });
  function end(){ if(!D) return; try{ D.hd.releasePointerCapture(D.pid); }catch(err){} D=null; }
  document.addEventListener('pointerup', end); document.addEventListener('pointercancel', end);
})();
function mmgDlgPlace(id, x, y){
  var b=document.getElementById(id);
  if(!b.style.left){ b.style.left=Math.max(8, Math.min(window.innerWidth-360, x))+'px'; b.style.top=Math.max(8, y)+'px'; }
  b.classList.add('on');
  var r=b.getBoundingClientRect();     // keep it on screen once its real size is known
  if(r.right>window.innerWidth-4) b.style.left=Math.max(4, window.innerWidth-r.width-4)+'px';
  if(r.bottom>window.innerHeight-4) b.style.top=Math.max(4, window.innerHeight-r.height-4)+'px';
}

/* ── Set timestamp ── */
function mmgTsOpen(uid){
  var it=mmgItem(uid); if(!it) return;
  MMG.ts=uid; document.getElementById('mmg-ts-title').textContent='Set timestamp — '+it.n;
  mmgTsFill(); document.getElementById('mmg-ts-status').textContent='';
  var inp=document.getElementById('mmg-ts-in'); inp.value=it.start.toFixed(3);
  mmgDlgPlace('mmg-ts', window.innerWidth/2-180, window.innerHeight/2-120);
  setTimeout(function(){ inp.focus(); inp.select(); }, 30);
}
function mmgTsFill(){
  var it=mmgItem(MMG.ts); if(!it) return;
  document.getElementById('mmg-ts-info').innerHTML =
    '<span>starts</span><b>'+mmgFmtMs(it.start)+'</b>'
    + '<span>finishes</span><b>'+mmgFmtMs(it.start+(it.dur||0))+'</b>'
    + '<span>length</span><b>'+mmgFmt(it.dur||0)+(it.d && Math.abs(it.d-(it.dur||0))>0.002?' <span style="font-weight:400">(source '+mmgFmt(it.d)+')</span>':'')+'</b>'
    + '<span>mix ends</span><b>'+mmgFmt(mmgTotal())+'</b>';
}
function mmgTsClose(){ MMG.ts=null; document.getElementById('mmg-ts').classList.remove('on'); }
function mmgTsApply(){
  var it=mmgItem(MMG.ts); if(!it) return;
  var t=mmgParseT(document.getElementById('mmg-ts-in').value), st=document.getElementById('mmg-ts-status');
  if(isNaN(t)){ st.textContent='not a time — try 1.250, 1250ms or 0:01.250'; st.style.color='var(--bad)'; return; }
  it.start=+Math.max(0,Math.min(3600,t)).toFixed(3); MMG.mixDirty=true;
  st.textContent='moved to '+mmgFmt(it.start); st.style.color='var(--good)';
  mmgRenderBoard(); mmgPersist();
  mmgRender({why:'move', play:true, from:Math.max(0,it.start-0.25)});
}

/* ── Tweak sound: knob dialog ── */
function mmgTweakRec(r){
  var its=mmgFind(r.c,r.f);
  if(its.length) mmgTweakOpen(its[its.length-1].uid);
  else mmgAdd(r, {then:function(){ var l=mmgFind(r.c,r.f); if(l.length) mmgTweakOpen(l[l.length-1].uid); }});
}
function mmgTweakOpen(uid, slotIdx){
  mmgSpec().then(function(){
    var it=mmgItem(uid); if(!it) return;
    if(slotIdx==null){                    /* no slot given: the item's first, adding one if it has none */
      it.slots=it.slots||[];
      if(!it.slots.length){ it.slots.push({type:'tweak', tweak:mmgDefaults()}); mmgSlotsChanged(it); if(MMG.mixer===uid) mmgMixerDraw(); }
      slotIdx=0;
    }
    var slot=it.slots[slotIdx]; if(!slot) return;
    MMG.tw=uid; MMG.twSlot=slotIdx;
    var et=mmgEffectType(slot.type), racks=(et&&et.racks)||MMG.spec.racks;
    document.getElementById('mmg-tw-title').textContent='Tweak — '+it.n+(et?' · '+et.title:'');
    document.getElementById('mmg-tw-body').innerHTML='<div class="mmg-racks">'+racks.map(function(r){
      return '<div class="mmg-rack"><h4>'+esc(r.title)+'</h4>'+(r.sub?'<div class="sub">'+esc(r.sub)+'</div>':'')
        + '<div class="mmg-knobs">'+r.params.map(mmgKnobHtml).join('')+'</div></div>';
    }).join('')+'</div>';
    mmgTwSyncAll(); mmgTwModeDraw();
    document.getElementById('mmg-tw-status').textContent = mmgIsDefault(slot.tweak, slot.type) ? 'all knobs at default' : 'tweaked';
    mmgDlgPlace('mmg-tweak', window.innerWidth-820, 70);
  }).catch(function(e){ alert('Mixer unavailable: '+(e.message||e)); });
}
function mmgTwT(it){ return (it&&it.slots&&it.slots[MMG.twSlot])?it.slots[MMG.twSlot].tweak:null; }
function mmgTwClose(){
  var uid=MMG.tw; MMG.tw=null; MMG.twSlot=null; clearTimeout(MMG.twTimer); MMG.stemPending=false;
  document.getElementById('mmg-tweak').classList.remove('on');
  if(!uid) return;
  var it=mmgItem(uid);
  if(MMG.stemPlaying){   /* loop means "keep playing the MERGED file" — a lone stem must not outlive its dialog */
    if(MMG.playing && it) mmgRender({why:'tweak', play:true, from:Math.max(0,it.start-0.25)});
    else mmgStop(true);
  }
  if(it && MMG.waveByUid[uid] && MMG.waveByUid[uid].dirty){ delete MMG.waveByUid[uid]; mmgRenderBoard(); }
}
function mmgKnobHtml(p){
  /* 2026-09-02: a select. Its value is the INDEX into p.opts, so the tweak
     dict stays numeric and hashes to the same stem on every client. It is NOT
     a knob with detents: the knob code drags on pointermove and a two-option
     control would flip on the smallest twitch. */
  if(p.type==='select'){
    var opts=(p.opts||[]).map(function(o,i){ return '<option value="'+i+'">'+esc(o.label)+'</option>'; }).join('');
    return '<div class="mk-sel" data-ctl="'+p.key+'" title="'+esc(p.hint||'')+'">'
      + '<select onchange="mmgTwSet(\''+p.key+'\', this.value)">'+opts+'</select>'
      + '<div class="kb-lab">'+esc(p.label)+'</div></div>';
  }
  if(p.type==='toggle'){
    return '<div class="mk-tog" data-ctl="'+p.key+'" title="'+esc(p.hint||'')+'"><div class="kb-lab">'+esc(p.label)+'</div><span class="vx-seg">'
      + '<button data-v="on" onclick="mmgTwSet(\''+p.key+'\',true)">on</button><button data-v="off" onclick="mmgTwSet(\''+p.key+'\',false)">off</button></span></div>';
  }
  return '<div class="mk-knob" data-ctl="'+p.key+'" title="'+esc(p.hint||'')+'"><svg viewBox="0 0 60 60" data-key="'+p.key+'">'
    + '<path class="kb-track" d="'+vsArc(30,30,23,-135,135)+'"></path><path class="kb-arc" d=""></path>'
    + '<circle class="kb-hub" cx="30" cy="30" r="14"></circle><line class="kb-ptr" x1="30" y1="30" x2="30" y2="19"></line></svg>'
    + '<div class="kb-lab">'+esc(p.label)+'</div><div class="kb-val"></div></div>';
}
function mmgTwSyncKnob(key){
  var it=mmgItem(MMG.tw), slot=it&&it.slots&&it.slots[MMG.twSlot], typ=slot&&slot.type;
  var p=mmgParam(key, typ), t=mmgTwT(it), el=document.querySelector('#mmg-tweak [data-ctl="'+key+'"]');
  if(!p||!t||!el) return;
  if(p.type==='toggle'){ var want=t[key]?'on':'off';
    Array.prototype.forEach.call(el.querySelectorAll('button'),function(b){ b.classList.toggle('on', b.getAttribute('data-v')===want); }); return; }
  if(p.type==='select'){
    var sel=el.querySelector('select'); if(sel) sel.value=String(Math.round(+t[key]||0));
    el.classList.toggle('mod', Math.round(+t[key]||0)!==Math.round(+p.def||0)); return; }
  var v=+t[key], frac=Math.max(0,Math.min(1,(v-p.min)/(p.max-p.min))), ang=-135+270*frac;
  var home=-135+270*Math.max(0,Math.min(1,(p.def-p.min)/(p.max-p.min)));
  el.querySelector('.kb-arc').setAttribute('d', vsArc(30,30,23,home,ang));
  var tip=vsPolar(30,30,11,ang), ln=el.querySelector('.kb-ptr');
  ln.setAttribute('x2',tip[0].toFixed(2)); ln.setAttribute('y2',tip[1].toFixed(2));
  el.querySelector('.kb-val').textContent = vsFmt(p,v);
  el.classList.toggle('mod', Math.abs(v-p.def)>1e-9);
}
function mmgTwSyncAll(){ if(!MMG.spec) return; var it=mmgItem(MMG.tw), slot=it&&it.slots&&it.slots[MMG.twSlot];
  var rs=mmgRacksFor(slot&&slot.type); if(!rs) return;
  rs.forEach(function(r){ r.params.forEach(function(p){ mmgTwSyncKnob(p.key); }); }); }
function mmgTwModeDraw(){
  Array.prototype.forEach.call(document.querySelectorAll('#mmg-tw-mode button'),function(b){ b.classList.toggle('on', b.getAttribute('data-v')===MMG.twMode); });
}
function mmgTwMode(m){
  MMG.twMode=m; mmgTwModeDraw();
  var it=mmgItem(MMG.tw); if(!it) return;
  if(m==='mix'){ if(!MMG.mix||MMG.mixDirty) mmgRender({why:'tweak', play:true, from:Math.max(0,it.start-0.25)}); else mmgPlay(Math.max(0,it.start-0.25)); mmgTwStatus('in the mix'); }
  else { if(it.url){ MMG.headBase=it.start; mmgPlayUrl(it.url, 0, true); } mmgTwStatus('isolated'); }
}
function mmgTwStatus(msg,col){ var s=document.getElementById('mmg-tw-status'); s.textContent=msg||''; s.style.color=col||'var(--muted)'; }
function mmgTwSet(key,val){
  var it=mmgItem(MMG.tw), slot=it&&it.slots&&it.slots[MMG.twSlot];
  var t=mmgTwT(it), p=mmgParam(key, slot&&slot.type); if(!t||!p) return;
  if(p.type==='toggle') t[key]=!!val;
  else if(p.type==='select'){ var i=Math.round(parseFloat(val)); if(isNaN(i)) return;
    t[key]=Math.max(0,Math.min((p.opts||[]).length-1,i)); }
  else { var n=parseFloat(val); if(isNaN(n)) return; t[key]=Math.max(p.min,Math.min(p.max,n)); }
  mmgTwSyncKnob(key); mmgTwChanged();
}
function mmgTwReset(){ var it=mmgItem(MMG.tw); if(!it||!it.slots||!it.slots[MMG.twSlot]) return;
  it.slots[MMG.twSlot].tweak=mmgDefaults(it.slots[MMG.twSlot].type); mmgTwSyncAll(); mmgTwChanged(); }
/* every twist → one stem render 160 ms after the last movement → play it */
function mmgTwChanged(){
  var it=mmgItem(MMG.tw); if(!it) return;
  MMG.mixDirty=true; mmgPersist();
  var card=document.querySelector('#mmg-lanes .mmg-card[data-uid="'+it.uid+'"]'); if(card) card.classList.toggle('tw', !!(it.slots&&it.slots.length));
  clearTimeout(MMG.twTimer); MMG.twTimer=setTimeout(mmgTwApply, 160);
}
function mmgTwApply(){
  var it=mmgItem(MMG.tw); if(!it) return;
  if(MMG.twMode==='mix'){
    mmgTwStatus('in the mix · rendering…');
    mmgRender({why:'tweak', play:true, from:Math.max(0,it.start-0.25),
              then:function(){ var i2=mmgItem(MMG.tw); if(i2) mmgTwStatus('in the mix · '+mmgFmt(i2.dur)); }});
    return;
  }
  /* one stem render at a time; a sweep folds into one follow-up of the latest knobs */
  if(MMG.stemBusy){ MMG.stemPending=true; return; }
  MMG.stemBusy=true; MMG.stemPending=false;
  var seq=++MMG.twSeq, slots=JSON.parse(JSON.stringify(it.slots||[])); mmgTwStatus('rendering…');
  vsPost('/inspect/api/merge/stem',{cat:it.c, f:it.f, slots:slots}).then(function(d){
    if(seq!==MMG.twSeq || MMG.tw!==it.uid) return;
    it.dur=d.dur; it.stem=d.stem; it.url=d.url; mmgRenderBoard(); mmgPersist();
    if(!MMG.stemPending){                 // knobs moved on: the follow-up will play the current ones
      MMG.headBase=it.start; mmgPlayUrl(d.url, 0, true);
      mmgTwStatus('isolated · '+mmgFmt(d.dur)+((it.slots&&it.slots.length)?'':' · default'));
    }
  }).catch(function(e){ mmgTwStatus('render failed: '+(e.message||e),'var(--bad)'); })
  .then(function(){ MMG.stemBusy=false; if(MMG.stemPending && MMG.tw===it.uid && MMG.twMode!=='mix'){ MMG.stemPending=false; mmgTwApply(); } else MMG.stemPending=false; });
}
/* knob dragging, the Voices tab's gestures on .mk-knob */
(function(){
  var DR=null;
  document.addEventListener('pointerdown',function(e){
    var svg=e.target.closest?e.target.closest('.mk-knob svg'):null; if(!svg) return;
    var it0=mmgItem(MMG.tw), slot0=it0&&it0.slots&&it0.slots[MMG.twSlot];
    var key=svg.getAttribute('data-key'), p=mmgParam(key, slot0&&slot0.type), t=mmgTwT(it0); if(!p||!t) return;
    e.preventDefault();
    DR={key:key,p:p,y:e.clientY,v0:+t[key],svg:svg,pid:e.pointerId,t:t};
    try{ svg.setPointerCapture(e.pointerId); }catch(err){} svg.parentElement.classList.add('drag');
  });
  document.addEventListener('pointermove',function(e){
    if(!DR) return;
    var span=DR.p.max-DR.p.min, fine=e.shiftKey?0.18:1.0;
    var v=DR.v0+((DR.y-e.clientY)/200)*span*fine;
    v=Math.max(DR.p.min,Math.min(DR.p.max,v));
    if(DR.p.step) v=DR.p.min+Math.round((v-DR.p.min)/DR.p.step)*DR.p.step;
    v=+v.toFixed(4);
    if(v!==DR.t[DR.key]){ DR.t[DR.key]=v; mmgTwSyncKnob(DR.key); mmgTwChanged(); }
  });
  function endDrag(){ if(!DR) return; try{ DR.svg.releasePointerCapture(DR.pid); }catch(err){} DR.svg.parentElement.classList.remove('drag'); DR=null; }
  document.addEventListener('pointerup',endDrag); document.addEventListener('pointercancel',endDrag);
  document.addEventListener('dblclick',function(e){
    var k=e.target.closest?e.target.closest('.mk-knob'):null; if(!k) return;
    var it0=mmgItem(MMG.tw), slot0=it0&&it0.slots&&it0.slots[MMG.twSlot];
    var key=k.getAttribute('data-ctl'), p=mmgParam(key, slot0&&slot0.type); if(!p) return; mmgTwSet(key,p.def);
  });
  document.addEventListener('wheel',function(e){
    var k=e.target.closest?e.target.closest('.mk-knob'):null; if(!k) return;
    var it0=mmgItem(MMG.tw), slot0=it0&&it0.slots&&it0.slots[MMG.twSlot];
    var key=k.getAttribute('data-ctl'), p=mmgParam(key, slot0&&slot0.type), t=mmgTwT(it0); if(!p||!t) return;
    e.preventDefault();
    var d=(e.deltaY<0?1:-1)*(p.step||1)*(e.shiftKey?1:5);
    mmgTwSet(key, +t[key]+d);
  },{passive:false});
})();

/* ── save / reopen / persist ── */
function mmgSave(){
  if(!MMG.items.length) return;
  var live=MMG.items.filter(function(i){ return !i.muted; });
  if(!live.length){ alert('Every layer is muted — nothing to save.'); return; }
  var def=MMG.lastName||('merge '+new Date().toISOString().slice(0,16).replace('T',' '));
  var name=prompt('Name for the mix (it lands in the Merged library):', def);
  if(name==null) return; name=name.trim(); if(!name) return;
  MMG.lastName=name; mmgStatus('saving…'); document.getElementById('mmg-save').disabled=true;
  var items=live.map(function(i){ return {uid:i.uid, cat:i.c, f:i.f, name:i.n, start:i.start, slots:i.slots}; });
  vsPost('/inspect/api/merge/save',{name:name, items:items}).then(function(d){
    mmgStatus('saved merged/'+d.file+(d.commercial_ok?'':' — licence UNVERIFIED'), d.commercial_ok?'var(--good)':'var(--warn)');
    mmgPersist();
    MUS.cat='merged'; MUS.sel=null; MUS.sort='new'; MUS.dir=-1;   // show it where it landed, newest first
    MUS.q=''; MUS.clean=false; MUS.noverbal=false;               // …and no filter may hide it
    musLoad(true);
  }).catch(function(e){ mmgStatus('save failed','var(--bad)'); alert('Save failed: '+(e.message||e)); })
  .then(function(){ document.getElementById('mmg-save').disabled=!MMG.items.length; });
}
function mmgOpenRecipe(r){
  api('/inspect/api/merge/recipe?f='+encodeURIComponent(r.f)).then(function(d){
    var rc=d.recipe; if(!rc||!rc.items) throw new Error(d.error||'no recipe');
    if(MMG.items.length && !confirm('Replace the current tracks with "'+rc.name+'" ('+rc.items.length+' tracks)?')) return;
    return mmgSpec().then(function(){
      var byKey={}; MUS.all.forEach(function(x){ byKey[x.c+'|'+x.f]=x; });
      var missing=rc.items.filter(function(i){ return !byKey[i.cat+'|'+i.f]; }).map(function(i){ return i.cat+'/'+i.f; });
      var items=rc.items.filter(function(i){ return byKey[i.cat+'|'+i.f]; }).map(function(i){ var src=byKey[i.cat+'|'+i.f];
        return {uid:mmgUid(), c:i.cat, f:i.f, n:i.name||src.n||i.f, d:src.d||0, start:+i.start||0,
                slots:Array.isArray(i.slots)?i.slots:[], dur:src.d||0, stem:'', url:''}; });
      if(missing.length) alert('Skipped '+missing.length+' source'+(missing.length===1?'':'s')+' no longer in the library:\n'+missing.join('\n'));
      if(!items.length){ mmgStatus('none of that mix\'s sources exist any more','var(--bad)'); return; }
      MMG.items=items; MMG.lastName=rc.name||''; MMG.sel=null; MMG.selIds=[]; MMG.seq++; MMG.pending=null; MMG.mix=null;
      mmgShow(); mmgRenderBoard(); mmgPersist();
      mmgRender({why:'add', play:true, from:0});
    });
  }).catch(function(e){ alert('Could not open that mix: '+(e.message||e)); });
}
function mmgPersist(){
  try{ localStorage.setItem('mus.merge', JSON.stringify({
    items:MMG.items.map(function(i){ return {uid:i.uid, c:i.c, f:i.f, n:i.n, d:i.d, start:i.start, slots:i.slots,
                                              label:i.label, color:i.color, muted:i.muted, hideName:i.hideName}; }),
    loop:MMG.loop, zoom:MMG.zoom, laneH:MMG.laneH, shown:MMG.shown, name:MMG.lastName})); }catch(e){}
}
/* a bare 'tweak' dict is a pre-slots localStorage entry from before the mixer
   had a slot list — wrap it as one slot, or drop it if it was never touched */
function mmgSlotsOf(i){
  if(Array.isArray(i.slots)) return i.slots;
  if(!i.tweak) return [];
  var t=Object.assign(mmgDefaults(), i.tweak);
  return mmgIsDefault(t) ? [] : [{type:'tweak', tweak:t}];
}
function mmgRestore(){
  if(MMG.restored) return; MMG.restored=true;
  var s=null; try{ s=JSON.parse(localStorage.getItem('mus.merge')||'null'); }catch(e){}
  /* 2026-09-05: the Sfx Studio leaves the panel hidden when there is nothing
     saved, and hides the header button that would bring it back — so a tab with
     an empty track list has NO board, NO ruler, NO transport and no control
     anywhere to get them.  It is invisible there only because a working browser
     always has a saved 'sx.merge'; on a fresh profile that tab is a void too.
     The track list IS this tab, so it comes up empty rather than not at all. */
  if(!s||!s.items||!s.items.length){ mmgShow(); mmgRenderBoard(); return; }
  var byKey={}; MUS.all.forEach(function(x){ byKey[x.c+'|'+x.f]=x; });
  MMG.loop=!!s.loop; MMG.zoom=+s.zoom||MMG.zoom; MMG.laneH=mmgLaneClamp(+s.laneH||46); MMG.lastName=s.name||'';
  mmgSpec().then(function(){
    MMG.items=s.items.filter(function(i){ return byKey[i.c+'|'+i.f]; }).map(function(i){ var src=byKey[i.c+'|'+i.f];
      return {uid:(/^[a-z0-9]{1,40}$/.test(String(i.uid||''))?i.uid:mmgUid()), c:i.c, f:i.f, n:src.n||i.n, d:src.d||i.d||0, start:Math.max(0,Math.min(600,+i.start||0)),
              slots:mmgSlotsOf(i), dur:src.d||i.d||0, stem:'', url:'',
              label:i.label||'', color:i.color||'', muted:!!i.muted, hideName:!!i.hideName}; });
    if(!MMG.items.length){ mmgRenderBoard(); return; }
    if(s.shown!==false) mmgShow(); else mmgHide();
    mmgRenderBoard();
    mmgRender({why:'restore', play:false});     // no autoplay on a reload; the ring is for adds
  }).catch(function(){ mmgRenderBoard(); });
}


