/* ── rendering ───────────────────────────────────────────────────────────── */
function voFind(id){
  for(var i=0;i<VO_TOOLS.length;i++) for(var j=0;j<VO_TOOLS[i].items.length;j++)
    if(VO_TOOLS[i].items[j].id===id) return VO_TOOLS[i].items[j];
  return null;
}
/* an icon is markup, not a character — same reasoning as arIcon */
function voIcon(t, cls){
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"'
    + ' stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"'
    + (cls?' class="'+cls+'"':'')+'>'+t.svg+'</svg>';
}
/* the latched state of the six tools that hold one, read from the state they
   actually toggle — there is no second copy of what is armed */
function voOn(t){
  if(t.id==='loop')     return !!S1.loop;
  if(t.id==='mloop')    return !!M1.loop;
  if(t.id==='merger')   return !!M1.shown;
  if(t.id==='onlypub')  return !!S1.clean;
  if(t.id==='onlyref')  return !!S1.noverbal;
  if(t.id==='bars')     return !!VO.bars;
  return false;
}
function voToolHtml(t){
  var st=t.st||'stub';
  return '<div class="vo-tool'+(voOn(t)?' on':'')+(st==='stub'?' stub':(st==='park'?' park':''))
    + '" data-vo="'+esc(t.id)+'" role="button" title="'+esc(String(t.lb))+' &mdash; '
    + String(t.tip).replace(/"/g,'&quot;')
    + (st==='park'?' [built, parked in the retired knob tab &mdash; click for where]'
       :(st==='stub'?' [not built &mdash; click for what it would do]':''))
    + '">'+voIcon(t)+'<span class="lb">'+esc(t.lb)+'</span></div>';
}
function voRender(){
  var side=document.getElementById('vo-tools');
  if(side) side.innerHTML = VO_TOOLS.filter(function(x){ return x.bar==='side'; })
    .map(function(sec){
      return '<div class="vo-tsec">'+esc(sec.sec)+'</div><div class="vo-trow">'
        + sec.items.map(voToolHtml).join('')+'</div>';
    }).join('');
  var dock=document.getElementById('vo-dock');
  if(dock) dock.innerHTML = '<div class="vo-dockgrid">'
    + VO_TOOLS.filter(function(x){ return x.bar==='dock'; }).map(function(sec){
        return '<div class="vo-dgrp"><span class="vo-dsec">'+esc(sec.sec)+'</span>'
          + '<div class="vo-drow">'+sec.items.map(voToolHtml).join('')+'</div></div>';
      }).join('') + '</div>';
}
/* a one-shot action cannot latch, so it acknowledges the click by lighting for
   420 ms — you can see the button took without it claiming a state it has not got */
function voFlash(id){
  Array.prototype.forEach.call(document.querySelectorAll('[data-vo="'+id+'"]'), function(el){
    el.classList.add('flash');
    setTimeout(function(){ el.classList.remove('flash'); }, 420);
  });
}
function voSay(msg,col){ if(window.m1Status) m1Status(msg, col||'var(--muted)'); }

/* ONE click handler for both bars, delegated, so the two can never drift apart
   about what a tool does. A parked or unbuilt tool opens its sheet instead of
   doing nothing. */
(function(){
  document.addEventListener('click', function(e){
    var el=e.target.closest ? e.target.closest('.vo-tool') : null;
    if(!el) return;
    var t=voFind(el.getAttribute('data-vo')); if(!t) return;
    if(t.st==='live' && t.act){
      voFlash(t.id);
      try{ (new Function(t.act))(); }
      catch(err){ voSay(t.lb+': '+(err.message||err),'var(--bad)'); }
      voRender();
      return;
    }
    if(t.st==='live' && t.knob){ voFlash(t.id); voTune(null, t.knob); return; }
    if(t.st==='live' && t.rack){ voFlash(t.id); voTune(t.rack, null); return; }
    voSheet(t);
  });
})();

/* ── the two bars themselves ─────────────────────────────────────────────── */
function voBarsToggle(){
  VO.bars=!VO.bars;
  try{ localStorage.setItem('vo.bars', VO.bars?'1':'0'); }catch(e){}
  voBarsApply();
}
function voDockToggle(){
  VO.dock=!VO.dock;
  try{ localStorage.setItem('vo.dock', VO.dock?'1':'0'); }catch(e){}
  voBarsApply();
}
/* both bars at once; the dock's own grip still works independently, so hiding
   and re-showing restores whatever the dock was set to rather than forcing it open */
function voBarsApply(){
  var col=document.getElementById('vo-toolcol'), a=document.getElementById('vo-arrow'),
      dk=document.getElementById('vo-dock'),     g=document.getElementById('vo-grip');
  if(col) col.classList.toggle('hid', !VO.bars);
  if(a){ a.innerHTML = VO.bars ? '&#9654;' : '&#9664;';
         a.title = VO.bars ? 'Hide both option bars' : 'Show both option bars'; }
  if(dk) dk.classList.toggle('off', !(VO.bars && VO.dock));
  if(g) g.classList.toggle('on', VO.dock);
  voRender();
}

/* ── the option sheet ────────────────────────────────────────────────────── */
var VO_BADGE={live:'live', park:'built &middot; parked', stub:'not built'};
function voSheet(t){
  VO.sheet=t.id;
  var st=t.st||'stub';
  var extra='';
  if(st==='park') extra = '<span class="k">Why you cannot click it</span><p>This panel is '
    + 'built and works. Its markup lives inside <code>#vx-main</code>, which is rendered into '
    + '<code>#view-voices</code> &mdash; the knob-panel tab retired on 2026-09-01 when this '
    + 'tab took the Voice Studio name. Nothing on the nav, in Settings or in the hash router '
    + 'reaches it any more, so <code>'+esc(t.fn||'')+'()</code> has a working function and no '
    + 'surface. The Tune and Assign dialogs escaped that fate only because they are fixed '
    + 'overlays declared outside the view.</p>';
  if(st==='stub') extra = '<span class="k">State</span><p>Not built. This icon is drawn so the '
    + 'option is visible as a gap rather than discovered as a surprise &mdash; it does not '
    + 'render, measure or save anything.</p>';
  document.getElementById('vo-box').innerHTML =
    '<div class="vo-hd">'+voIcon(t)+'<h3>'+esc(t.lb)+'</h3>'
    + '<span class="vo-badge '+st+'">'+VO_BADGE[st]+'</span><span class="sp"></span>'
    + '<button class="vo-arrow" onclick="voSheetClose()" title="Close">&times;</button></div>'
    + '<div class="vo-bd"><p>'+t.what+'</p>'
    + '<span class="k">Where it sits</span><p>'+esc(t.where)+'</p>'
    + extra + '</div>';
  document.getElementById('vo-info').classList.add('on');
}
function voSheetClose(){ VO.sheet=null; document.getElementById('vo-info').classList.remove('on'); }

/* ── the voice this tab has selected ─────────────────────────────────────── */
function voVoiceId(){
  if(S1.curRec) return S1.curRec.f;
  if(S1.shown && S1.shown.length) return S1.shown[0].f;
  return '';
}
function voVoiceRec(){
  var id=voVoiceId(); if(!id) return null;
  for(var i=0;i<S1.all.length;i++) if(S1.all[i].f===id) return S1.all[i];
  return null;
}
/* ── booting the parked VS state onto the voice selected HERE ─────────────
   #vx-tune and #vx-assign are fixed overlays declared outside #view-voices, so
   they are still reachable — what they had lost was a VS.spec / VS.st to draw
   from, because only vsEnter() ever filled those and nothing calls vsEnter()
   any more. This fills them on demand for the voice selected in THIS tab.
   vsRenderMain() writes into the retired tab's hidden #vx-main on the way past,
   which is harmless and is also what leaves every [data-ctl] element present
   for vsSyncAll to find. */
function voBootVS(cb){
  var vid=voVoiceId();
  if(!vid){ voSay('Pick a voice in the list first.','var(--warn)'); return; }
  if(VO.booting) return;
  var afterSpec=function(){
    if(VS.st && VS.voice===vid){ cb(); return; }
    VO.booting=true;
    VS.voice=vid;
    vsApi('/voice/api/state?voice='+encodeURIComponent(vid)).then(function(d){
      VO.booting=false; VS.st=d;
      try{ vsRenderRail(); }catch(e){}
      vsRenderMain(); cb();
    }).catch(function(e){
      VO.booting=false; voSay('could not load '+vid+' — '+(e.message||e),'var(--bad)');
    });
  };
  if(VS.spec) return afterSpec();
  VO.booting=true;
  vsApi('/voice/api/spec').then(function(d){
    VO.booting=false; VS.spec=d; VS.booted=true;
    VS.params=JSON.parse(JSON.stringify(d.defaults));
    afterSpec();
  }).catch(function(e){
    VO.booting=false; voSay('voice studio unavailable — '+(e.message||e),'var(--bad)');
  });
}
/* Open Tune on the selected voice and, when the tool named one, scroll that
   rack or that single knob into view and ring it, so 24 different rail icons
   land 24 different places in one dialog instead of all landing at the top. */
function voTune(rack, knob){
  voBootVS(function(){
    vsTuneOpen();
    if(!rack && !knob) return;
    var sel = knob ? '#vx-tunebox [data-ctl="'+knob+'"]' : '#vx-tunebox #vx-rack-'+rack;
    var el=document.querySelector(sel);
    if(!el){ return; }
    if(el.scrollIntoView) el.scrollIntoView({block:'center'});
    var prev=el.style.boxShadow;
    el.style.boxShadow='0 0 0 2px var(--acc)';
    el.style.borderRadius='10px';
    setTimeout(function(){ el.style.boxShadow=prev; }, 1600);
  });
}
function voAssign(){ voBootVS(function(){ vsAsOpen(); }); }

/* ── the live session tools ──────────────────────────────────────────────── */
function voPlay(){
  var a=document.getElementById('s1-audio');
  if(!S1.curRec){ s1Step(1); return; }
  if(a.paused) a.play().catch(function(){}); else a.pause();
}
function voLoop(){
  S1.loop=!S1.loop;
  var a=document.getElementById('s1-audio'); if(a) a.loop=S1.loop;
  voSay('take loop '+(S1.loop?'on':'off'));
}
function voMerger(){ if(M1.shown) m1Hide(); else m1Show(); }
function voTweakHint(){
  if(!M1.items.length){ voSay('Add a take to the merge board first — right-click a voice.','var(--warn)'); return; }
  if(M1.items[0] && M1.items[0].uid!=null) m1MixerOpen(M1.items[0].uid);
  else voSay('Right-click a card on the board to tweak that layer.');
}
function voExport(){
  var a=document.getElementById('s1-audio'), src=a && a.getAttribute('src');
  if(!src){ voSay('Nothing is loaded — play a voice first.','var(--warn)'); return; }
  var name=(S1.curRec ? S1.curRec.f : 'take')+'.wav';
  var l=document.createElement('a'); l.href=src; l.download=name;
  document.body.appendChild(l); l.click(); document.body.removeChild(l);
  voSay('downloading '+name);
}
function voSearch(){
  var i=document.querySelector('#s1-bar input[type=search]');
  if(i){ i.focus(); i.select(); } else voSay('The search box is in the list header.','var(--warn)');
}
function voBanks(){
  var b=document.getElementById('s1-bar');
  if(b && b.scrollIntoView) b.scrollIntoView({block:'nearest'});
  voSay(S1.cat ? ('bank: '+s1CatLabel(S1.cat)+' — click a chip to change it')
                : 'all banks — click a chip in the list header to narrow');
}
function voSort(){
  var keys=['pack','name','age','bank'], i=keys.indexOf(S1.sort);
  var k=keys[(i+1)%keys.length];
  try{ s1Sort(k); }catch(e){ S1.sort=k; s1Render(); }
  voSay('sorted by '+k);
}
function voRefresh(){ s1Load(true); voSay('re-pulling the voice registry…'); }

/* ── measurement, read from the take that is loaded ───────────────────────
   Nothing here re-measures: a baked take carries the metrics it was published
   with, so this reads them rather than paying Praat's 1.3 s again — and it says
   plainly when a take has none instead of printing a zero. */
function voMetrics(verdictOnly){
  var r=S1.curRec;
  if(!r){ voSay('Play a voice first — the meters read the take that is loaded.','var(--warn)'); return; }
  var b=S1.base[r.f]||{}, m=b.metrics||null;
  var rows='';
  if(!m){
    rows = '<p>This take carries no measurement. A take is measured when it is rendered '
      + 'in the knob panel; the library bake stores what it measured, and this one has '
      + 'nothing stored. That is a gap in the bake, not a fault in the voice.</p>';
  } else {
    var f0=(m.f0_med!=null?m.f0_med:m.f0), vtl=(m.vtl!=null?m.vtl:m.vtl_cm);
    rows = '<span class="k">Measured</span><p>'
      + (f0!=null?('Median F0 <code>'+(Math.round(f0*10)/10)+' Hz</code><br>'):'')
      + (vtl!=null?('Vocal tract <code>'+(Math.round(vtl*100)/100)+' cm</code><br>'):'')
      + (m.wpm!=null?('Pace <code>'+Math.round(m.wpm)+' wpm</code><br>'):'')
      + (m.lufs!=null?('Loudness <code>'+(Math.round(m.lufs*10)/10)+' LUFS</code>'):'')
      + '</p>';
    if(m.verdict||m.band) rows += '<span class="k">voice_qc</span><p>'
      + esc(String(m.verdict||''))+(m.band?(' &mdash; band <code>'+esc(String(m.band))+'</code>'):'')+'</p>';
    else if(verdictOnly) rows += '<span class="k">voice_qc</span><p>No verdict stored with this '
      + 'take. The numbers above are the measurement; the band check is a separate step and it '
      + 'did not run here.</p>';
    rows += '<span class="k">Read this way</span><p>14.5 cm is the practical vocal-tract floor '
      + 'for a male read on this box &mdash; adult female measured 14.44, so anything under it '
      + 'reads female whatever the label says. The female caution line is 13.0 cm, not 14.5; '
      + 'copying Abel&#39;s across sexes would fire on every correct female render.</p>';
  }
  document.getElementById('vo-box').innerHTML =
    '<div class="vo-hd">'+voIcon(voFind(verdictOnly?'qc':'meters'))
    + '<h3>'+esc(r.n||r.f)+'</h3><span class="vo-badge live">live</span>'
    + '<span class="sp"></span><button class="vo-arrow" onclick="voSheetClose()">&times;</button></div>'
    + '<div class="vo-bd">'+rows+'</div>';
  document.getElementById('vo-info').classList.add('on');
}
/* ── licence and publication, read from the registry row ─────────────────── */
function voLicence(policyOnly){
  var r=voVoiceRec();
  if(!r){ voSay('Pick a voice in the list first.','var(--warn)'); return; }
  var pub = (r.publishable===true) ? 'yes' : (r.publishable===false ? 'no' : 'not recorded');
  var h='<span class="k">Voice</span><p><code>'+esc(r.f)+'</code>'
    + (r.role?(' &mdash; '+esc(r.role)):'')+'</p>'
    + '<span class="k">Source bank</span><p>'+esc(String(r.source||'unrecorded'))+'</p>'
    + '<span class="k">Licence</span><p>'+esc(String(r.licence||r.license||'not carried on this row'))+'</p>'
    + '<span class="k">May reach published audio</span><p>'+pub
    + (r.publish_reason?(' &mdash; '+esc(String(r.publish_reason))):'')+'</p>';
  if(policyOnly) h += '<span class="k">Why this matters here</span><p>The channel is monetised, '
    + 'so a voice that may not be published is a live exposure and not paperwork. The rail&#39;s '
    + '&quot;publishable only&quot; filter reads this same policy, so the filter and the answer '
    + 'above can never disagree.</p>';
  else h += '<span class="k">The rule this codebase follows</span><p>Licence is checked at FILE '
    + 'level, never at the root of a pack. The Kyutai bank is CC0 <em>plus</em> donor consent for '
    + 'speech-model use &mdash; a basis a licence alone never gives, and the reason it beats the '
    + 'CC BY 4.0 banks. Licence-clean is also not content-clean: nobody has listened through this '
    + 'bank for slates or surprises.</p>';
  document.getElementById('vo-box').innerHTML =
    '<div class="vo-hd">'+voIcon(voFind(policyOnly?'pub':'lic'))+'<h3>'+esc(r.n||r.f)+'</h3>'
    + '<span class="vo-badge live">live</span><span class="sp"></span>'
    + '<button class="vo-arrow" onclick="voSheetClose()">&times;</button></div>'
    + '<div class="vo-bd">'+h+'</div>';
  document.getElementById('vo-info').classList.add('on');
}
function voKeys(){
  document.getElementById('vo-box').innerHTML =
    '<div class="vo-hd">'+voIcon(voFind('keys'))+'<h3>Keys</h3>'
    + '<span class="vo-badge live">live</span><span class="sp"></span>'
    + '<button class="vo-arrow" onclick="voSheetClose()">&times;</button></div>'
    + '<div class="vo-bd">'
    + '<span class="k">The voice list</span><p><code>&uarr;</code> / <code>&darr;</code> step to '
    + 'the previous or next voice and play it &mdash; they walk what is SHOWN, so a filter narrows '
    + 'the walk. <code>space</code> plays or pauses. <code>Esc</code> stops and releases the '
    + 'player.</p>'
    + '<span class="k">Who owns a key</span><p>The merger takes <code>&larr;</code> / '
    + '<code>&rarr;</code> / <code>Delete</code> whenever it has a card selected, and '
    + '<code>space</code> and <code>Esc</code> along with them; the list only sees a key the '
    + 'merger did not claim. Typing in any field takes precedence over both.</p>'
    + '<span class="k">The merge board</span><p>Drag a card to move it; <code>&larr;</code> / '
    + '<code>&rarr;</code> nudge by 1 ms, <code>shift</code> 10 ms, <code>ctrl</code> 100 ms. '
    + '<code>ctrl</code>+wheel zooms on the pointer, <code>ctrl</code>+<code>shift</code>+wheel '
    + 'makes the lanes taller.</p>'
    + '<span class="k">The bars</span><p>Every icon carries its own hover text. A dashed icon '
    + 'with a violet dot is built but parked; with an amber dot it is not built. Both open a '
    + 'sheet that says so.</p></div>';
  document.getElementById('vo-info').classList.add('on');
}
/* the whole list on one sheet — 109 icons is not a thing anyone should have to
   click through to find out what this studio can be asked to do */
function voIndex(){
  var n={live:0, park:0, stub:0}, body='';
  VO_TOOLS.forEach(function(sec){
    body += '<span class="k">'+esc(sec.sec)+' &middot; '
         + (sec.bar==='side'?'right rail':'bottom bar')+'</span><p>'
         + sec.items.map(function(t){
             n[t.st]=(n[t.st]||0)+1;
             var mark = t.st==='live' ? '' : (t.st==='park' ? ' &middot; <em>parked</em>'
                                                            : ' &middot; <em>not built</em>');
             return esc(t.lb)+mark;
           }).join('<br>') + '</p>';
  });
  document.getElementById('vo-box').innerHTML =
    '<div class="vo-hd">'+voIcon(voFind('index'))+'<h3>All options</h3>'
    + '<span class="vo-badge live">'+n.live+' live</span>'
    + '<span class="vo-badge park">'+n.park+' parked</span>'
    + '<span class="vo-badge stub">'+n.stub+' not built</span>'
    + '<span class="sp"></span><button class="vo-arrow" onclick="voSheetClose()">&times;</button></div>'
    + '<div class="vo-bd"><p>Every option in both bars. <b>Live</b> works from this tab. '
    + '<b>Parked</b> is built and working but its panel lives in the retired knob tab. '
    + '<b>Not built</b> is drawn here so the gap is visible; click any icon for what it would '
    + 'do and where in the chain it would attach.</p>'+body+'</div>';
  document.getElementById('vo-info').classList.add('on');
}
/* Esc closes the sheet before the tab's own Esc gets to stop the player.
   Guarded on the dialog's own class, NOT on VO.sheet: only voSheet() sets that
   name, so the meters, licence, keys and index sheets — which open the same
   box directly — were left unclosable by Esc while the tab's handler underneath
   happily stopped the player instead. The visible state is the one to read. */
document.addEventListener('keydown', function(e){
  if(e.key!=='Escape') return;
  var box=document.getElementById('vo-info');
  if(box && box.classList.contains('on')){ e.stopPropagation(); voSheetClose(); }
}, true);

function voEnter(){
  try{ var b=localStorage.getItem('vo.bars'); if(b!==null) VO.bars=(b==='1');
       var d=localStorage.getItem('vo.dock'); if(d!==null) VO.dock=(d==='1'); }catch(e){}
  voBarsApply();
}


